33	/** The periods on a sheet: listed, added, closed and reopened. */
34	@Service
35	public class PeriodService {
36	
37	    private final PeriodRepository periods;
38	    private final ClaimRepository claims;
39	    private final PersonRepository people;
40	    private final Dues dues;
41	    private final SheetService sheets;
42	    private final RoleService roles;
43	    private final Audit audit;
44	    private final SheetHistory history;
45	    private final RolloverRepository rollovers;
46	
47	    public PeriodService(PeriodRepository periods, ClaimRepository claims, PersonRepository people, Dues dues,
48	            SheetService sheets, RoleService roles, Audit audit, SheetHistory history, RolloverRepository rollovers) {
49	        this.rollovers = rollovers;
50	        this.history = history;
51	        this.periods = periods;
52	        this.claims = claims;
53	        this.people = people;
54	        this.dues = dues;
55	        this.sheets = sheets;
56	        this.roles = roles;
57	        this.audit = audit;
58	    }
59	
60	    /** The sheet's periods by from-date. */
61	    @Transactional(readOnly = true)
62	    public List<Period> list(String sheetId) {
63	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
64	    }
65	
66	    /**
67	     * Add a period to the sheet; refused when its from-date is after its to-date, when its name is
68	     * already in use on the sheet, or when it shares a day with another period. A cap, when given,
69	     * is the most OPEN or PENDING claims due by in it a person may have (see {@link #refuseIfCapped});
70	     * it must be at least 1, and PERIOD_ADDED ends with cap=&lt;n&gt;.
71	     */
72	    @Transactional
73	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
74	        // Take the sheet's lock first, so two periods added at once cannot both pass the checks.
75	        sheets.lock(sheetId);
76	        if (from.isAfter(to)) {
77	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's from-date cannot be after its to-date.");
78	        }
79	        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
80	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
81	        }
82	        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
83	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another period on this sheet.");
84	        }
85	        if (cap != null && cap < 1) {
86	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1.");
87	        }
88	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
89	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
90	                + " from=" + period.getFromDate() + " to=" + period.getToDate()
91	                + (period.getClaimCap() != null ? " cap=" + period.getClaimCap() : ""));
92	        return period;
93	    }
94	
95	    /**
96	     * Generate one period per calendar month from the from-date's month to the to-date's month, each
97	     * running from the first to the last day of its month and named yyyy-mm, in month order. A month
98	     * whose name is already a period on the sheet, or whose days overlap one, is left out and the others
99	     * are still made. Refused when the to-date is before the from-date.
100	     */
101	    @Transactional
102	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
103	        // Take the sheet's lock first, so no period added meanwhile slips past the checks.
104	        sheets.lock(sheetId);
105	        if (to.isBefore(from)) {
106	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
107	        }
108	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
109	        List<Period> made = new ArrayList<>();
110	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
111	            addGenerated(sheetId, user, month.toString(), month.atDay(1), month.atEndOfMonth(), existing, made);
112	        }
113	        return made;
114	    }
115	
116	    /**
117	     * Generate the four calendar quarters of {@code year}, each running from the first day of its first
118	     * month to the last day of its third and named yyyy-Q1 to yyyy-Q4, in order. A quarter whose name is
119	     * already a period on the sheet, or whose days overlap one, is left out and the others are still made.
120	     */
121	    @Transactional
122	    public List<Period> generateQuarters(String sheetId, String user, int year) {
123	        // Take the sheet's lock first, so no period added meanwhile slips past the checks.
124	        sheets.lock(sheetId);
125	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
126	        List<Period> made = new ArrayList<>();
127	        for (int quarter = 1; quarter <= 4; quarter++) {
128	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
129	            addGenerated(sheetId, user, year + "-Q" + quarter, start.atDay(1), start.plusMonths(2).atEndOfMonth(),
130	                    existing, made);
131	        }
132	        return made;
133	    }
134	
135	    /** Add a generated period unless its name is taken or its days overlap an existing one, as the form would. */
136	    private void addGenerated(String sheetId, String user, String name, LocalDate first, LocalDate last,
137	            List<Period> existing, List<Period> made) {
138	        if (existing.stream().anyMatch(p -> p.getName().toLowerCase(Locale.ROOT).equals(Period.keyOf(name))
139	                || p.overlaps(first, last))) {
140	            return;
141	        }
142	        Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
143	        existing.add(period);
144	        made.add(period);
145	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
146	                + " from=" + period.getFromDate() + " to=" + period.getToDate());
147	    }
148	
149	    /**
150	     * Generate the twelve monthly periods of the fiscal year named FY{@code year}, from the first day of
151	     * the sheet's fiscal start month in that year, exactly as {@link #generate} does.
152	     */
153	    @Transactional
154	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
155	        LocalDate first = sheets.lock(sheetId).fiscalYearStart(year);
156	        return generate(sheetId, user, first, first.plusYears(1).minusDays(1));
157	    }
158	
159	    /**
160	     * Roll fiscal year FY{@code year} over: generate the next fiscal year's twelve periods exactly as
161	     * {@link #generateFiscalYear} does, then add each person's open figure at the end of the old year's
162	     * last period to their opening balance for the new year's first period, each as an OPENING_SET, and
163	     * record ROLLOVER with how many periods were made. A person's open figure is the sum of the due
164	     * figures, as computed now, of their claims due by in a period of the old year (a period whose
165	     * from-date falls in it) that were OPEN or PENDING at the end of the old year's last period by their
166	     * status log, each at the grade its person has in force on its date, leaving out the same claims as
167	     * {@link #carried}; a person whose figure is nothing gets no line, and no one gets one when no period
168	     * was made. Then soft-close, in from-date order, each period of the old year still open, exactly as
169	     * {@link #softClose} would, each recorded PERIOD_SOFT_CLOSED after the ROLLOVER line. Refused for anyone but a steward,
170	     * and when the old year has no periods. The rollover is kept, with the periods it made and the
171	     * opening balances it set, so it can be undone (see {@link #undoRollover}). The periods made, in month order.
172	     */
173	    @Transactional
174	    public List<Period> rollover(String sheetId, String user, int year) {
175	        Sheet sheet = sheets.lock(sheetId);
176	        LocalDate today = sheet.getToday();
177	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
178	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll the year over.");
179	        }
180	        List<Period> old = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
181	                .filter(p -> sheet.fiscalYearOf(p.getFromDate()) == year)
182	                .toList();
183	        if (old.isEmpty()) {
184	            throw new ResponseStatusException(HttpStatus.CONFLICT, "FY" + year + " has no periods to roll over.");
185	        }
186	        LocalDate end = old.stream().map(Period::getToDate).max(Comparator.naturalOrder()).orElseThrow();
187	        Map<Long, BigDecimal> open = openAt(sheetId, old, end, today);
188	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
189	        Rollover rollover = new Rollover(sheetId, user, today, year);
190	        made.forEach(p -> rollover.addPeriod(p.getId()));
191	        // A rollover that made no periods (the year was already rolled over) carries nothing again.
192	        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
193	                .filter(p -> !made.isEmpty() && sheet.fiscalYearOf(p.getFromDate()) == year + 1)
194	                .findFirst()
195	                .ifPresent(first -> {
196	                    for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
197	                        BigDecimal amount = open.get(person.getId());
198	                        if (amount == null || amount.signum() == 0) {
199	                            continue;
200	                        }
201	                        first.addOpening(person.getId(), amount);
202	                        periods.saveAndFlush(first);
203	                        rollover.addOpening(first.getId(), person.getId(), amount);
204	                        audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
205	                                + " period=" + first.getName() + " amount=" + amount.toPlainString());
206	                    }
207	                });
208	        rollovers.saveAndFlush(rollover);
209	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=FY" + year + " periods=" + made.size());
210	        for (Period period : old) {
211	            if (!period.isFixed()) {
212	                softCloseFixing(sheetId, user, period, today);
213	            }
214	        }
215	        return made;
216	    }
217	
218	    /**
219	     * Undo the sheet's last rollover: remove the periods it generated and take back the opening balances
220	     * it set, and record ROLLOVER_UNDONE with the fiscal year it rolled over. Refused when there is no
221	     * rollover left to undo, for anyone but the steward who made it, on any day of the sheet but the one
222	     * it was made on, and when a claim's date or due-by falls in one of the periods it generated.
223	     */
224	    @Transactional
225	    public void undoRollover(String sheetId, String user) {
226	        Sheet sheet = sheets.lock(sheetId);
227	        Rollover rollover = rollovers.findFirstBySheetIdOrderByIdDesc(sheetId)
228	                .filter(r -> !r.isUndone())
229	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no rollover to undo."));
230	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user)) || !rollover.getMadeBy().equals(user)) {
231	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who made the rollover may undo it.");
232	        }
233	        if (!Objects.equals(rollover.getMadeOn(), sheet.getToday())) {
234	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rollover can only be undone on the day it was made.");
235	        }
236	        List<Period> made = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
237	                .filter(p -> rollover.getPeriodIds().contains(p.getId()))
238	                .toList();
239	        boolean used = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
240	                .anyMatch(c -> made.stream().anyMatch(p -> (c.getDate() != null && p.contains(c.getDate()))
241	                        || (c.getDueBy() != null && p.contains(c.getDueBy()))));
242	        if (used) {
243	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim now belongs to a period the rollover generated.");
244	        }
245	        if (rollover.getOpeningPeriodId() != null && !rollover.getPeriodIds().contains(rollover.getOpeningPeriodId())) {
246	            periods.findByIdAndSheetId(rollover.getOpeningPeriodId(), sheetId).ifPresent(period -> {
247	                rollover.getOpenings().forEach(period::takeOpening);
248	                periods.saveAndFlush(period);
249	            });
250	        }
251	        periods.deleteAll(made);
252	        periods.flush();
253	        rollover.undo();
254	        rollovers.saveAndFlush(rollover);
255	        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=FY" + rollover.getFy());
256	    }
257	
258	    /**
259	     * Each person's open figure at the end of a day, by person id: the sum of the due figures of their
260	     * claims due by in one of the given periods that were OPEN or PENDING then (see {@link #rollover}).
261	     */
262	    private Map<Long, BigDecimal> openAt(String sheetId, List<Period> within, LocalDate end, LocalDate today) {
263	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
264	                .collect(Collectors.toMap(Person::getId, person -> person));
265	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
266	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
267	            Person person = byId.get(claim.getPersonId());
268	            if (person == null || within.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
269	                continue;
270	            }
271	            ClaimStatus then = claim.statusAt(end);
272	            if (then == null || !then.isOpen() || claim.isDeferredOn(today)
273	                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
274	                continue;
275	            }
276	            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
277	            if (figure != null) {
278	                open.merge(person.getId(), figure.setScale(2), BigDecimal::add);
279	            }
280	        }
281	        return open;
282	    }
283	
284	    /**
285	     * Close a period, fixing at this moment each person's due-total and carried figure (see {@link #carried})
286	     * for it and its own due-total, their sum. A person's is the sum of the due figures,
287	     * as computed now, of the claims due by in it that were OPEN, PENDING or SETTLED at the end of its last day by their status log, each at
288	     * the grade its person has in force on its date (a claim with no figure adds nothing), leaving out those still OPEN or PENDING and dated
289	     * within their person's hold or of a person whose retirement date is reached, unless bound by a statement, and those deferred on today. Each pool
290	     * member's cut for it is fixed too, as it stands now (see {@link SheetHistory#cutsNow}). A soft-closed period closes with its figures
291	     * fixed afresh. Refused when the period is already closed, or for a role the sheet's permission matrix does not allow.
292	     */
293	    @Transactional
294	    public Period close(String sheetId, String user, long periodId) {
295	        // Take the sheet's lock first, so no claim in the period changes while its total is fixed.
296	        LocalDate today = sheets.lock(sheetId).getToday();
297	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
298	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
299	        if (!roles.permits(sheetId, user, "close")) {
300	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
301	        }
302	        if (period.isClosed()) {
303	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
304	        }
305	        return fix(sheetId, user, period, today, "");
306	    }
307	
308	    /**
309	     * Soft-close an open period: its due-total and each person's figure for it are fixed as on a close
310	     * (see {@link #close}), while claims due by in it can still be added and changed. Refused when the
311	     * period is already closed or soft-closed, or for a role the sheet's permission matrix does not
312	     * allow to close.
313	     */
314	    @Transactional
315	    public Period softClose(String sheetId, String user, long periodId) {
316	        LocalDate today = sheets.lock(sheetId).getToday();
317	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
318	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
319	        if (!roles.permits(sheetId, user, "close")) {
320	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
321	        }
322	        if (period.isFixed()) {
323	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed or soft-closed.");
324	        }
325	        return softCloseFixing(sheetId, user, period, today);
326	    }
327	
328	    /** Soft-close an open period, fixing its figures as they stand now, and record PERIOD_SOFT_CLOSED. */
329	    private Period softCloseFixing(String sheetId, String user, Period period, LocalDate today) {
330	        period.softClose(totals(sheetId, period, today), carried(sheetId, period, today));
331	        period.fixCuts(history.cutsNow(sheetId, today));
332	        Period saved = periods.saveAndFlush(period);
333	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
334	                + " total=" + saved.getClosedTotal().toPlainString());
335	        return saved;
336	    }
337	
338	    /**
339	     * The sheet's today was changed: close, in order of their to-dates, each open period whose to-date
340	     * plus the sheet's grace days is before the new today, exactly as a close by hand would, its
341	     * PERIOD_CLOSED marked auto=yes. A soft-closed period keeps the figures fixed for it and is left as
342	     * it is. Nothing closes while the grace days are off.
343	     */
344	    @EventListener
345	    public void todayChanged(TodayChanged change) {
346	        if (change.graceDays() == null) {
347	            return;
348	        }
349	        LocalDate today = sheets.lock(change.sheetId()).getToday();
350	        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(change.sheetId()).stream()
351	                .filter(p -> !p.isFixed() && p.getToDate().plusDays(change.graceDays()).isBefore(today))
352	                .sorted(Comparator.comparing(Period::getToDate))
353	                .toList();
354	        for (Period period : due) {
355	            fix(change.sheetId(), change.user(), period, today, " auto=yes");
356	        }
357	    }
358	
359	    /** Close an open or soft-closed period, fixing its totals as of today, and audit it with the given trailing fields. */
360	    private Period fix(String sheetId, String user, Period period, LocalDate today, String trailing) {
361	        period.close(totals(sheetId, period, today), carried(sheetId, period, today));
362	        period.fixCuts(history.cutsNow(sheetId, today));
363	        Period saved = periods.saveAndFlush(period);
364	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
365	                + " total=" + saved.getClosedTotal().toPlainString() + trailing);
366	        return saved;
367	    }
368	
369	    /** Each person's due-total for the period as of today, by person id (see {@link #close}). */
370	    private Map<Long, BigDecimal> totals(String sheetId, Period period, LocalDate today) {
371	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
372	                .collect(Collectors.toMap(Person::getId, person -> person));
373	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
374	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
375	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
376	            Person person = byId.get(claim.getPersonId());
377	            if (person == null || !period.contains(claim.getDueBy())) {
378	                continue;
379	            }
380	            ClaimStatus then = claim.statusAt(period.getToDate());
381	            if (then == null || !then.counts() || claim.isDeferredOn(today)
382	                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
383	                continue;
384	            }
385	            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
386	            if (figure != null) {
387	                totals.merge(person.getId(), figure, BigDecimal::add);
388	            }
389	        }
390	        return totals;
391	    }
392	
393	    /**
394	     * Each person's carried figure for the period as of today, by person id: the sum of the due figures,
395	     * as computed now, of their claims due by in a period ending before this one starts that were OPEN or
396	     * PENDING at the end of this one's last day by their status log, each at the grade its person has in
397	     * force on its date, leaving out the same claims as {@link #totals}, plus their opening balance for it.
398	     */
399	    private Map<Long, BigDecimal> carried(String sheetId, Period period, LocalDate today) {
400	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
401	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
402	                .collect(Collectors.toMap(Person::getId, person -> person));
403	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
404	        byId.keySet().forEach(id -> carried.put(id,
405	                period.getPersonOpenings().getOrDefault(id, BigDecimal.ZERO).setScale(2)));
406	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
407	            Person person = byId.get(claim.getPersonId());
408	            boolean earlier = all.stream().filter(p -> p.contains(claim.getDueBy())).findFirst()
409	                    .map(own -> own.getToDate().isBefore(period.getFromDate())).orElse(false);
410	            if (person == null || !earlier) {
411	                continue;
412	            }
413	            ClaimStatus then = claim.statusAt(period.getToDate());
414	            if (then == null || !then.isOpen() || claim.isDeferredOn(today)
415	                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
416	                continue;
417	            }
418	            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
419	            if (figure != null) {
420	                carried.merge(person.getId(), figure, BigDecimal::add);
421	            }
422	        }
423	        return carried;
424	    }
425	
426	    /**
427	     * Reopen a closed or soft-closed period: its due-total and pool cuts are live again, the claims due by in it counting at their
428	     * current figures. Refused for a role the sheet's permission matrix
429	     * does not allow (anyone but a steward by default), when the period is neither closed nor soft-closed,
430	     * and while it is locked.
431	     */
432	    @Transactional
433	    public Period reopen(String sheetId, String user, long periodId) {
434	        LocalDate today = sheets.lock(sheetId).getToday();
435	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
436	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
437	        if (!roles.permits(sheetId, user, "reopen")) {
438	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period.");
439	        }
440	        if (!period.isFixed()) {
441	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
442	        }
443	        if (period.isLocked()) {
444	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is locked.");
445	        }
446	        period.reopen();
447	        Period saved = periods.saveAndFlush(period);
448	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
449	        return saved;
450	    }
451	
452	    /**
453	     * Lock or unlock a period: a locked period cannot be reopened. Refused for anyone but a steward,
454	     * when locking a period already locked, and when unlocking one not locked.
455	     */
456	    @Transactional
457	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
458	        sheets.lock(sheetId);
459	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
460	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
461	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
462	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may lock or unlock a period.");
463	        }
464	        if (period.isLocked() == lock) {
465	            throw new ResponseStatusException(HttpStatus.CONFLICT,
466	                    lock ? "The period is already locked." : "The period is not locked.");
467	        }
468	        period.setLocked(lock);
469	        Period saved = periods.saveAndFlush(period);
470	        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
471	                + " period=" + saved.getName());
472	        return saved;
473	    }
474	
475	    /**
476	     * Give out the number for a claim due by a date (its due-by) as it is settled or approved, holding the sheet's lock until
477	     * the caller's transaction ends. While the sheet numbers by period (see {@link Sheet#numbersByPeriod})
478	     * it is the next within the period the date falls in, {@code <period name>-<n>}, or {@code X-<n>}
479	     * when it falls in none; otherwise it is the next sheet-wide number of the sheet's tree within the
480	     * fiscal year (by the sheet's fiscal start month) the date falls in, {@code FY<year>-<n>}, after the
481	     * last given in that fiscal year on any sheet of it. The tree's root is locked too, so the sheets of
482	     * a tree take their numbers one at a time.
483	     */
484	    @Transactional
485	    public String nextClaimNumber(String sheetId, LocalDate date) {
486	        Sheet sheet = sheets.lock(sheetId);
487	        if (!sheet.numbersByPeriod()) {
488	            List<String> tree = sheets.tree(sheetId);
489	            sheets.lock(tree.get(0));
490	            int year = sheet.fiscalYearOf(date);
491	            int lastInTree = tree.stream().filter(id -> !id.equals(sheetId))
492	                    .mapToInt(id -> sheets.load(id).getLastClaimNumberIn(year)).max().orElse(0);
493	            return "FY" + year + "-" + sheet.nextClaimNumberIn(year, lastInTree);
494	        }
495	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
496	                .filter(p -> p.contains(date))
497	                .findFirst()
498	                .map(p -> p.getName() + "-" + p.nextClaimNumber())
499	                .orElseGet(() -> "X-" + sheet.nextUnperiodClaimNumber());
500	    }
501	
502	    /** The name of the period a date falls in on the sheet; null when it falls in none. */
503	    @Transactional(readOnly = true)
504	    public String periodOn(String sheetId, LocalDate date) {
505	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
506	                .filter(p -> p.contains(date))
507	                .findFirst()
508	                .map(Period::getName)
509	                .orElse(null);
510	    }
511	
512	    /** Whether the date falls inside one of the sheet's soft-closed periods. */
513	    @Transactional(readOnly = true)
514	    public boolean softClosedOn(String sheetId, LocalDate date) {
515	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
516	                .anyMatch(p -> p.isSoftClosed() && p.contains(date));
517	    }
518	
519	    /**
520	     * Refuse opening a claim due by a date (its due-by) inside a period with a claim cap when its person
521	     * already has that many OPEN or PENDING claims due by in the period.
522	     */
523	    public void refuseIfCapped(String sheetId, Claim claim) {
524	        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
525	                .filter(p -> p.getClaimCap() != null && p.contains(claim.getDueBy()))
526	                .findFirst()
527	                .ifPresent(period -> {
528	                    long open = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
529	                            .filter(c -> !c.getId().equals(claim.getId()) && c.getStatus().isOpen()
530	                                    && period.contains(c.getDueBy()))
531	                            .count();
532	                    if (open >= period.getClaimCap()) {
533	                        throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has "
534	                                + period.getClaimCap() + " open claims in period " + period.getName() + ".");
535	                    }
536	                });
537	    }
538	
539	    /** Refuse a change to a claim due by a date (its due-by) inside one of the sheet's closed periods. */
540	    public void refuseIfClosed(String sheetId, LocalDate date) {
541	        if (periods.findBySheetIdAndClosedTrue(sheetId).stream().anyMatch(p -> p.contains(date))) {
542	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is due by inside a closed period.");
543	        }
544	    }
545	}
