20	/**
21	 * A period on a sheet: a name, unique on the sheet ignoring case by its {@link #keyOf key}, and a
22	 * from and to date, both inclusive. No two periods on a sheet overlap. A closed period keeps the
23	 * due-total it had when it was closed, and each person's due-total and carried figure for it then, until
24	 * it is reopened.
25	 * A soft-closed period fixes them the same way, but claims due by in it can still change; it can be
26	 * closed (fixing them afresh) or reopened.
27	 */
28	@Entity
29	@Table(name = "period")
30	public class Period {
31	
32	    @Id
33	    @GeneratedValue(strategy = GenerationType.IDENTITY)
34	    private Long id;
35	
36	    @Column(name = "sheet_id", nullable = false)
37	    private String sheetId;
38	
39	    @Column(name = "name", nullable = false)
40	    private String name;
41	
42	    @Column(name = "name_key", nullable = false)
43	    private String nameKey;
44	
45	    @Column(name = "from_date", nullable = false)
46	    private LocalDate fromDate;
47	
48	    @Column(name = "to_date", nullable = false)
49	    private LocalDate toDate;
50	
51	    @Column(name = "closed", nullable = false)
52	    private boolean closed;
53	
54	    /** Whether the period is soft-closed: its figures fixed, its claims still open to change. */
55	    @Column(name = "soft_closed", nullable = false)
56	    private boolean softClosed;
57	
58	    /** Whether a steward has locked the period: a locked period cannot be reopened. */
59	    @Column(name = "locked", nullable = false)
60	    private boolean locked;
61	
62	    @Column(name = "closed_total")
63	    private BigDecimal closedTotal;
64	
65	    /** Each person's due-total for the period fixed when it was closed, by person id; empty while open. */
66	    @ElementCollection(fetch = FetchType.EAGER)
67	    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
68	    @MapKeyColumn(name = "person_id")
69	    @Column(name = "total", nullable = false)
70	    private Map<Long, BigDecimal> personTotals = new HashMap<>();
71	
72	    /** Each person's carried figure for the period fixed when it was closed, by person id; empty while open. */
73	    @ElementCollection(fetch = FetchType.EAGER)
74	    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
75	    @MapKeyColumn(name = "person_id")
76	    @Column(name = "carried", nullable = false)
77	    private Map<Long, BigDecimal> personCarried = new HashMap<>();
78	
79	    /** Each person's opening balance for the period, the sum of the amounts imported for them, by person id. */
80	    @ElementCollection(fetch = FetchType.EAGER)
81	    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
82	    @MapKeyColumn(name = "person_id")
83	    @Column(name = "amount", nullable = false)
84	    private Map<Long, BigDecimal> personOpenings = new HashMap<>();
85	
86	    /** The last number the period gave a claim opened in it under period numbering; 0 before any. */
87	    @Column(name = "last_claim_number", nullable = false)
88	    private int lastClaimNumber;
89	
90	    /** The most OPEN or PENDING claims due by in the period a person may have; null for no cap. */
91	    @Column(name = "claim_cap")
92	    private Integer claimCap;
93	
94	    /**
95	     * What the period's pool cuts are worked out from, fixed when it was closed or soft-closed, as JSON
96	     * (see {@link net.officefloor.hq.app.history.SheetHistory#cutsNow}); null while open.
97	     */
98	    @Column(name = "cuts")
99	    private String cuts;
100	
101	    protected Period() {
102	    }
103	
104	    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
105	        this(sheetId, name, fromDate, toDate, null);
106	    }
107	
108	    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer claimCap) {
109	        this.sheetId = sheetId;
110	        this.name = clean(name);
111	        this.nameKey = keyOf(name);
112	        this.fromDate = fromDate;
113	        this.toDate = toDate;
114	        this.claimCap = claimCap;
115	    }
116	
117	    /** The name as it is kept: surrounding spaces removed. */
118	    public static String clean(String name) {
119	        return name.trim();
120	    }
121	
122	    /** The key a name is unique by on its sheet: kept as cleaned, ignoring case. */
123	    public static String keyOf(String name) {
124	        return clean(name).toLowerCase(Locale.ROOT);
125	    }
126	
127	    public Long getId() {
128	        return id;
129	    }
130	
131	    public String getSheetId() {
132	        return sheetId;
133	    }
134	
135	    public String getName() {
136	        return name;
137	    }
138	
139	    public LocalDate getFromDate() {
140	        return fromDate;
141	    }
142	
143	    public LocalDate getToDate() {
144	        return toDate;
145	    }
146	
147	    /** The most OPEN or PENDING claims due by in the period a person may have; null for no cap. */
148	    public Integer getClaimCap() {
149	        return claimCap;
150	    }
151	
152	    public boolean isClosed() {
153	        return closed;
154	    }
155	
156	    public boolean isSoftClosed() {
157	        return softClosed;
158	    }
159	
160	    public boolean isLocked() {
161	        return locked;
162	    }
163	
164	    /** Lock or unlock the period. */
165	    public void setLocked(boolean locked) {
166	        this.locked = locked;
167	    }
168	
169	    /** Whether the period's figures are fixed: it is closed or soft-closed. */
170	    public boolean isFixed() {
171	        return closed || softClosed;
172	    }
173	
174	    /** The due-total fixed when the period was closed; null while it is open. */
175	    public BigDecimal getClosedTotal() {
176	        return closedTotal;
177	    }
178	
179	    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
180	    public Map<Long, BigDecimal> getPersonTotals() {
181	        return Map.copyOf(personTotals);
182	    }
183	
184	    /** Each person's carried figure fixed when the period was closed, by person id; empty while it is open. */
185	    public Map<Long, BigDecimal> getPersonCarried() {
186	        return Map.copyOf(personCarried);
187	    }
188	
189	    /** Each person's opening balance for the period, by person id; a person with none is not listed. */
190	    public Map<Long, BigDecimal> getPersonOpenings() {
191	        return Map.copyOf(personOpenings);
192	    }
193	
194	    /** Add an amount to the person's opening balance for the period. */
195	    public void addOpening(long personId, BigDecimal amount) {
196	        personOpenings.merge(personId, amount, BigDecimal::add);
197	    }
198	
199	    /** Take an amount back off the person's opening balance for the period; a balance of nothing is removed. */
200	    public void takeOpening(long personId, BigDecimal amount) {
201	        BigDecimal left = personOpenings.getOrDefault(personId, BigDecimal.ZERO).subtract(amount);
202	        if (left.signum() == 0) {
203	            personOpenings.remove(personId);
204	        } else {
205	            personOpenings.put(personId, left);
206	        }
207	    }
208	
209	    /** Close the period, fixing each person's due-total and carried figure for it and its own due-total, their sum. */
210	    public void close(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
211	        fixTotals(totals, carried);
212	        this.closed = true;
213	        this.softClosed = false;
214	    }
215	
216	    /** Soft-close the period, fixing its figures as a close does while its claims stay open to change. */
217	    public void softClose(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
218	        fixTotals(totals, carried);
219	        this.softClosed = true;
220	    }
221	
222	    private void fixTotals(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
223	        this.personTotals.clear();
224	        this.personTotals.putAll(totals);
225	        this.personCarried.clear();
226	        this.personCarried.putAll(carried);
227	        this.closedTotal = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
228	    }
229	
230	    /** What the period's pool cuts were fixed from when it was closed, as JSON; null while it is open. */
231	    public String getCuts() {
232	        return cuts;
233	    }
234	
235	    /** Fix what the period's pool cuts are worked out from, as JSON. */
236	    public void fixCuts(String cuts) {
237	        this.cuts = cuts;
238	    }
239	
240	    /** Reopen the period: its due-total and pool cuts are live again. */
241	    public void reopen() {
242	        this.cuts = null;
243	        this.closed = false;
244	        this.softClosed = false;
245	        this.closedTotal = null;
246	        this.personTotals.clear();
247	        this.personCarried.clear();
248	    }
249	
250	    /** Whether the date falls inside this period (inclusive). */
251	    public boolean contains(LocalDate date) {
252	        return !fromDate.isAfter(date) && !toDate.isBefore(date);
253	    }
254	
255	    /** Whether this period shares any day with the inclusive range {@code from} to {@code to}. */
256	    public boolean overlaps(LocalDate from, LocalDate to) {
257	        return !fromDate.isAfter(to) && !toDate.isBefore(from);
258	    }
259	
260	    /** Give out the period's next claim number: 1 for the first, then 2, and so on. */
261	    public int nextClaimNumber() {
262	        return ++lastClaimNumber;
263	    }
264	}
