2	
3	import java.math.BigDecimal;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.regex.Pattern;
7	import net.officefloor.hq.app.Audit;
8	import net.officefloor.hq.app.person.Person;
9	import net.officefloor.hq.app.person.PersonRepository;
10	import net.officefloor.hq.app.sheet.SheetService;
11	import org.springframework.http.HttpStatus;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	import org.springframework.web.server.ResponseStatusException;
15	
16	/**
17	 * The opening balances import: lines of name,period,amount each add the amount to the named person's
18	 * (by name or alias) opening balance for the named period on the sheet, which adds to their carried
19	 * figure for it. The amount has two decimals and is 0.00 or more. Every line is checked first; it is one
20	 * change, so when any line is refused nothing is added and nothing is recorded.
21	 */
22	@Service
23	public class OpeningService {
24	
25	    /** An opening amount: two decimals, 0.00 or more. */
26	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}\\.\\d{2}");
27	
28	    /** The most lines one import takes. */
29	    static final int LINES_MAX = 1000;
30	
31	    /** A line read from the import, checked. */
32	    private record Line(Person person, Period period, BigDecimal amount) {
33	    }
34	
35	    private final PersonRepository people;
36	    private final PeriodRepository periods;
37	    private final SheetService sheets;
38	    private final Audit audit;
39	
40	    public OpeningService(PersonRepository people, PeriodRepository periods, SheetService sheets, Audit audit) {
41	        this.people = people;
42	        this.periods = periods;
43	        this.sheets = sheets;
44	        this.audit = audit;
45	    }
46	
47	    /** Add each line's amount to its person's opening balance for its period, in order; how many lines went through. */
48	    @Transactional
49	    public int importOpenings(String sheetId, String user, String text) {
50	        // Take the sheet's lock first, so no person or period changes while the lines are checked and kept.
51	        sheets.lock(sheetId);
52	        List<Line> lines = new ArrayList<>();
53	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
54	        for (int i = 0; i < raw.length; i++) {
55	            if (!raw[i].isBlank()) {
56	                lines.add(line(sheetId, i + 1, raw[i]));
57	            }
58	        }
59	        if (lines.isEmpty()) {
60	            throw refused("Paste at least one line of name,period,amount.");
61	        }
62	        if (lines.size() > LINES_MAX) {
63	            throw refused("Paste at most " + LINES_MAX + " lines at once.");
64	        }
65	        for (Line line : lines) {
66	            line.period().addOpening(line.person().getId(), line.amount());
67	            periods.saveAndFlush(line.period());
68	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + line.person().getName()
69	                    + " period=" + line.period().getName() + " amount=" + line.amount().toPlainString());
70	        }
71	        return lines.size();
72	    }
73	
74	    private Line line(String sheetId, int number, String text) {
75	        String[] fields = text.split(",", -1);
76	        if (fields.length != 3) {
77	            throw refused("Line " + number + " needs a name, a period and an amount.");
78	        }
79	        String name = fields[0].trim();
80	        if (name.isEmpty()) {
81	            throw refused("Line " + number + " has no name.");
82	        }
83	        Person person = people.findBySheetIdAndName(sheetId, name)
84	                .orElseThrow(() -> refused("Line " + number + ": " + name + " is not on this sheet."));
85	        String periodName = fields[1].trim();
86	        Period period = periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(periodName))
87	                .orElseThrow(() -> refused("Line " + number + ": " + periodName + " is not a period on this sheet."));
88	        String amount = fields[2].trim();
89	        if (!AMOUNT.matcher(amount).matches()) {
90	            throw refused("Line " + number + ": the amount must have two decimals and be 0.00 or more.");
91	        }
92	        return new Line(person, period, new BigDecimal(amount));
93	    }
94	
95	    private static ResponseStatusException refused(String reason) {
96	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
97	    }
98	}
