 16	/** What is due on a claim, read from the rates its person's grade has. */
 17	@Component
 18	public class Dues {
 19	
 20	    private final RateRepository rates;
 21	    private final SheetRepository sheets;
 22	    private final ClaimRepository claims;
 23	
 24	    public Dues(RateRepository rates, SheetRepository sheets, ClaimRepository claims) {
 25	        this.rates = rates;
 26	        this.sheets = sheets;
 27	        this.claims = claims;
 28	    }
 29	
 30	    /** How many levels of parent sheets a grade with no rate in force falls back to. */
 31	    public static final int PARENT_LEVELS = 3;
 32	
 33	    /**
 34	     * What a claim's figures are read against: the sheet (its today and its dated settings; null when
 35	     * not found), the sheet's rates, its ancestors' rates (nearest first, up to {@link #PARENT_LEVELS}),
 36	     * and how the claim a correction names is found.
 37	     */
 38	    public record Basis(Sheet sheet, List<Rate> rates, List<List<Rate>> inherited,
 39	            Function<Claim, Optional<Claim>> corrected) {
 40	
 41	        /**
 42	         * The rate in force for a grade on a date (see {@link RateRepository#findInForce}); when the sheet
 43	         * has none, its parent's, then its parent's parent's, and so on; then the sheet it was cloned from.
 44	         */
 45	        public Optional<Rate> rateInForce(String grade, LocalDate date) {
 46	            Optional<Rate> rate = RateRepository.inForce(rates, grade, date);
 47	            for (int level = 0; rate.isEmpty() && level < inherited.size(); level++) {
 48	                rate = RateRepository.inForce(inherited.get(level), grade, date);
 49	            }
 50	            return rate;
 51	        }
 52	
 53	        /**
 54	         * The rate in force for a grade on a claim's date as the claim sees the rates: a forward-only rate
 55	         * saved after the claim was added is passed over (see {@link RateRepository#inForceFor}); when the
 56	         * sheet has none, its parent's, then its parent's parent's, and so on; then the sheet it was cloned from.
 57	         */
 58	        public Optional<Rate> rateInForceFor(Claim claim, String grade) {
 59	            Optional<Rate> rate = RateRepository.inForceFor(rates, grade, claim.getDate(), claim.getAdded());
 60	            for (int level = 0; rate.isEmpty() && level < inherited.size(); level++) {
 61	                rate = RateRepository.inForceFor(inherited.get(level), grade, claim.getDate(), claim.getAdded());
 62	            }
 63	            return rate;
 64	        }
 65	
 66	        LocalDate today() {
 67	            return sheet == null ? null : sheet.getToday();
 68	        }
 69	    }
 70	
 71	    /** The sheet as the store holds it now: what every live figure is read against. */
 72	    public Basis live(String sheetId) {
 73	        return new Basis(sheets.findById(sheetId).orElse(null), rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId),
 74	                inherited(sheetId), claim -> claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects()));
 75	    }
 76	
 77	    /**
 78	     * The rates of the sheet's ancestors as the store holds them now, nearest first, up to
 79	     * {@link #PARENT_LEVELS}; then, for a cloned sheet, those of the sheet it was cloned from, its
 80	     * ancestors and its source, and so on (see {@link SheetRepository#rateSources}).
 81	     */
 82	    public List<List<Rate>> inherited(String sheetId) {
 83	        return sheets.rateSources(sheetId, PARENT_LEVELS).stream()
 84	                .map(rates::findBySheetIdOrderByGradeAscFromDateAscIdAsc).toList();
 85	    }
 86	
 87	    /**
 88	     * How a claim's live figures round: by the sheet's policy date against the claim's date, or for a
 89	     * correction the date of the claim it corrects (its own when that claim is not found).
 90	     */
 91	    private RoundingMode rounding(Claim claim, Basis basis) {
 92	        LocalDate date = claim.getDate();
 93	        if (claim.getCorrects() != null) {
 94	            date = basis.corrected().apply(claim).map(Claim::getDate).orElse(date);
 95	        }
 96	        Sheet sheet = basis.sheet();
 97	        return sheet == null ? RoundingMode.HALF_EVEN : sheet.roundingOn(date);
 98	    }
 99	
100	    /**
101	     * The due figure a claim shows, before its late charge and floor: the one fixed when it was settled,
102	     * else the figure its person's last statement bound it to (its whole due as shown then, late charge
103	     * included), else its amount at the rate the grade has in force on the claim's date; null (n/a) when there is none.
104	     */
105	    public BigDecimal figure(Claim claim, String grade) {
106	        return figure(claim, grade, live(claim.getSheetId()));
107	    }
108	
109	    /** The due figure a claim shows (see {@link #figure(Claim, String)}), read against a basis. */
110	    public BigDecimal figure(Claim claim, String grade, Basis basis) {
111	        if (claim.getSettledDue() != null) {
112	            return claim.getSettledDue();
113	        }
114	        return claim.isStated() ? claim.getStatedDue() : live(claim, grade, basis);
115	    }
116	
117	    /**
118	     * The due a claim shows: the greater of the floor in force on its date and its figure (see
119	     * {@link #figure}), with the late charge worked out on that floored figure on top while it is overdue; a settled claim's figure is
120	     * frozen as it was settled, and a claim a statement bound shows the due it bound, its late charge no
121	     * longer following the sheet's today. Null (n/a) when it has no figure.
122	     */
123	    public BigDecimal due(Claim claim, String grade) {
124	        return due(claim, grade, live(claim.getSheetId()));
125	    }
126	
127	    /** The due a claim shows (see {@link #due(Claim, String)}), read against a basis. */
128	    public BigDecimal due(Claim claim, String grade, Basis basis) {
129	        if (claim.getSettledDue() != null) {
130	            return claim.getSettledDue();
131	        }
132	        if (boundWhole(claim)) {
133	            return claim.getStatedDue();
134	        }
135	        return withLate(claim, grade, floored(claim, figure(claim, grade, basis), basis), basis);
136	    }
