138	    /**
139	     * Whether a statement bound the claim's whole due as shown, late charge and floor included (a
140	     * figure bound before statements bound the late charge is the rate figure alone).
141	     */
142	    private static boolean boundWhole(Claim claim) {
143	        return claim.isStated() && claim.isStatedWhole();
144	    }
145	
146	    /**
147	     * The due a claim is settled at: the due a statement bound it to, else its live figure raised to
148	     * the floor, with the late charge it has on the sheet's today worked out on that on top; null when it has no figure.
149	     */
150	    public BigDecimal settling(Claim claim, String grade) {
151	        if (boundWhole(claim)) {
152	            return claim.getStatedDue();
153	        }
154	        Basis basis = live(claim.getSheetId());
155	        return withLate(claim, grade, floored(claim, claim.isStated() ? claim.getStatedDue() : live(claim, grade, basis), basis), basis);
156	    }
157	
158	    /**
159	     * The due a PENDING claim is approved at: the figure a statement bound it to, else its live figure,
160	     * with the late charge it has on the sheet's today on top; null when it has no figure.
161	     */
162	    public BigDecimal approving(Claim claim, String grade) {
163	        return settling(claim, grade);
164	    }
