166	    /**
167	     * The due a SETTLED claim is re-settled at: what it would show today as an OPEN claim bound by no
168	     * statement, its live figure raised to the floor with the late charge it would have on the sheet's today on top (none
169	     * when its late charge was waived); null when it has no figure.
170	     */
171	    public BigDecimal resettling(Claim claim, String grade) {
172	        Basis basis = live(claim.getSheetId());
173	        BigDecimal figure = live(claim, grade, basis);
174	        if (figure == null || claim.isCorrection()) {
175	            return figure;
176	        }
177	        BigDecimal floored = floored(claim, figure, basis);
178	        return claim.isWaived() ? floored : lateOn(claim, grade, floored, basis);
179	    }
180	
181	    /**
182	     * A figure with the claim's late charge on top while an OPEN or PENDING claim is past its due-by
183	     * (fixed when it was added) on the sheet's today (see {@link #lateOn}), rounded by the claim's date
184	     * against the policy date. The charge follows the sheet's today until a statement binds it with the figure.
185	     * A correction has no late charge, nor has a claim deferred on the sheet's today (it is not overdue),
186	     * nor a claim whose late charge was waived.
187	     */
188	    private BigDecimal withLate(Claim claim, String grade, BigDecimal figure, Basis basis) {
189	        if (figure == null || claim.isCorrection() || claim.isWaived() || !claim.getStatus().isOpen() || claim.getSettledDue() != null) {
190	            return figure;
191	        }
192	        if (basis.sheet() != null && claim.isDeferredOn(basis.today())) {
193	            return figure;
194	        }
195	        return lateOn(claim, grade, figure, basis);
196	    }
197	
198	    /**
199	     * A figure with the late charge an OPEN claim would have on the sheet's today on top: for every full
200	     * 30 days past its due-by plus its grade's grace (see {@link Sheet#lateFrom}), the late percent in
201	     * force on that boundary date (that date plus 30, 60, 90 ... days) of the figure plus the charges of
202	     * the boundaries before it (the charge compounds), rounded like the claim, the charges added up.
203	     */
204	    private BigDecimal lateOn(Claim claim, String grade, BigDecimal figure, Basis basis) {
205	        Sheet sheet = basis.sheet();
206	        if (sheet == null) {
207	            return figure;
208	        }
209	        LocalDate dueBy = sheet.lateFrom(claim.getDueBy(), grade, claim.getDate());
210	        long periods = ChronoUnit.DAYS.between(dueBy, sheet.getToday()) / 30;
211	        RoundingMode rounding = rounding(claim, basis);
212	        BigDecimal late = BigDecimal.ZERO.setScale(2);
213	        for (long period = 1; period <= periods; period++) {
214	            BigDecimal latePct = sheet.latePctOn(dueBy.plusDays(30 * period));
215	            if (latePct != null && latePct.signum() != 0) {
216	                late = late.add(figure.add(late).multiply(latePct).movePointLeft(2).setScale(2, rounding));
217	            }
218	        }
219	        return figure.add(late);
220	    }
221	
222	    /**
223	     * A figure raised to the floor in force on the claim's date when below it, applied first (the late
224	     * charge is worked out on the floored figure); a correction has no floor, and null (n/a) stays null.
225	     */
226	    private BigDecimal floored(Claim claim, BigDecimal due, Basis basis) {
227	        if (due == null || claim.isCorrection()) {
228	            return due;
229	        }
230	        Sheet sheet = basis.sheet();
231	        BigDecimal floor = sheet == null ? null : sheet.floorOn(claim.getDate());
232	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
233	    }
234	
235	    /**
236	     * A claim's rate figure: its amount at the rate the grade has in force on the claim's date as the
237	     * claim sees the rates (a forward-only rate saved after it was added passed over), rounded
238	     * by the claim's date against the policy date, with no floor; null when it has no rate.
239	     */
240	    public BigDecimal live(Claim claim, String grade) {
241	        return live(claim, grade, live(claim.getSheetId()));
242	    }
243	
244	    private BigDecimal live(Claim claim, String grade, Basis basis) {
245	        RoundingMode rounding = rounding(claim, basis);
246	        return basis.rateInForceFor(claim, grade)
247	                .map(rate -> due(claim.getAmount(), rate, rounding))
248	                .orElse(null);
249	    }
250	
251	    /**
252	     * A holder's part of a shared claim whose due figure is given: the claim's amount times their share
253	     * over 100, times the rate their own grade (the one in force for them on the claim's date) has in
254	     * force on the claim's date as the claim sees the rates, over 100, rounded like the claim; null
255	     * (0.00) when their grade has no rate. A settled claim keeps its parts as frozen: its frozen figure
256	     * times the share over 100 (see {@link ClaimShare#partOf}).
257	     */
258	    public BigDecimal part(Claim claim, ClaimShare share, String holderGrade, BigDecimal figure, Basis basis) {
259	        if (claim.getSettledDue() != null) {
260	            return share.partOf(figure);
261	        }
262	        RoundingMode rounding = rounding(claim, basis);
263	        return basis.rateInForceFor(claim, holderGrade)
264	                .map(rate -> claim.getAmount().multiply(share.getShare()).multiply(rate.getPct())
265	                        .movePointLeft(4).setScale(2, rounding))
266	                .orElse(null);
267	    }
268	
269	    /** What is due on an amount at a rate: the amount times the percent over 100, rounded as given. */
270	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
271	        return amount.multiply(rate.getPct()).movePointLeft(2).setScale(2, rounding);
272	    }
273	}
