276	/**
277	 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT,
278	 * OPEN or PENDING one voided. An OPEN claim a clerk settles above the clerk limit goes PENDING, which
279	 * a steward approves (SETTLED) or rejects (back to OPEN). A steward may void a SETTLED claim within
280	 * {@link #VOID_SETTLED_DAYS} days of its settlement; VOID is final. A DRAFT claim may be DELETED, and
281	 * restored to a DRAFT on the sheet's today it was deleted. A DRAFT opened while its due is above the
282	 * sheet's review threshold goes to REVIEW instead, which a steward reviews (OPEN) and anyone may void.
283	 * Only OPEN, PENDING and SETTLED claims count.
284	 */
285	public enum ClaimStatus {
286	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
287	
288	    /** The days after its settlement (by the sheet's today) a SETTLED claim may still be voided. */
289	    public static final int VOID_SETTLED_DAYS = 7;
290	
291	    /** Whether a claim may move from this status to {@code next}. */
292	    public boolean canBecome(ClaimStatus next) {
293	        return switch (next) {
294	            case OPEN, REVIEW -> this == DRAFT;
295	            case SETTLED, PENDING -> this == OPEN;
296	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
297	            case DELETED -> this == DRAFT;
298	            case DRAFT -> this == DELETED;
299	        };
300	    }
301	
302	    /** Whether a claim in this status counts toward what is claimed and due. */
303	    public boolean counts() {
304	        return this == OPEN || this == PENDING || this == SETTLED;
305	    }
306	
307	    /** Whether a claim in this status is open: OPEN, or PENDING a steward's approval. */
308	    public boolean isOpen() {
309	        return this == OPEN || this == PENDING;
310	    }
311	}
