82	    /** Add a person as {@link #add(String, String, String, String, Integer, String)} does, with their tags, comma separated (null or blank: none). */
83	    @Transactional
84	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact,
85	            String tags) {
86	        sheets.load(sheetId);
87	        requireGradeOpen(sheetId, grade);
88	        requireNameFree(sheetId, name, null);
89	        requireContactFree(sheetId, contact, null);
90	        Rollups.Rollup before = rollups.take(sheetId);
91	        Person added = new Person(sheetId, name, grade, terms, contact);
92	        added.tag(Claim.tagsOf(tags));
93	        added.setPosition(people.findMaxPositionBySheetId(sheetId) + 1);
94	        Person person = people.saveAndFlush(added);
95	        audited("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId), terms != null,
96	                person.getContact() != null);
97	        rollups.audit(sheetId, user, before);
98	        return person;
