128	    /**
129	     * Edit a person as {@link #edit} does; a grade chosen on the form (gradeGiven) is recorded from its
130	     * date even when it is already in force there.
131	     */
132	    @Transactional
133	    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
134	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, boolean termsGiven,
135	            boolean contactGiven, String tags, boolean gradeGiven) {
136	        Person person = people.findByIdAndSheetId(personId, sheetId)
137	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
138	        if (person.getVersion() != version) {
139	            throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
140	                    "Someone else has saved this person since it was opened.");
141	        }
142	        // People on a retired grade keep it, but it cannot be chosen for them, nor given to anyone else.
143	        LocalDate gradeOn = gradeFrom != null ? gradeFrom : sheets.today(sheetId);
144	        if (gradeGiven || !grade.equals(person.gradeOn(gradeOn))) {
145	            requireGradeOpen(sheetId, grade);
146	        }
147	        requireNameFree(sheetId, name, person.getId());
148	        if (person.getAliases().stream().map(Person::keyOf).anyMatch(treeKeys(sheetId)::contains)) {
149	            throw nameInUse();
150	        }
151	        requireContactFree(sheetId, contact, person.getId());
152	        Rollups.Rollup before = rollups.take(sheetId);
153	        LocalDate today = sheets.today(sheetId);
154	        boolean withTerms = termsGiven || (termsFrom == null
155	                ? !java.util.Objects.equals(person.getTerms(), terms)
156	                : !person.hasTermsFrom(termsFrom) || !java.util.Objects.equals(person.getTermsFrom().get(termsFrom), terms));
157	        boolean withContact = contactGiven
158	                || !java.util.Objects.equals(person.getContact(), Person.contactOf(contact));
159	        person.setName(name);
160	        if (termsFrom == null) {
161	            person.setTerms(terms);
162	        } else {
163	            person.termsFrom(terms, termsFrom);
164	        }
165	        person.setContact(contact);
166	        if (tags != null) {
167	            person.tag(Claim.tagsOf(tags));
168	        }
169	        // A grade already in force from the sheet's today is not recorded again, so it does not hold over a
170	        // grade recorded later from an earlier date, unless it was chosen on the form; one given from another
171	        // date is recorded from it.
172	        LocalDate from = gradeFrom != null ? gradeFrom : today;
173	        boolean dated = (gradeGiven || !from.equals(today)) && !grade.equals(person.getGradesFrom().get(from));
174	        if (dated || !grade.equals(person.gradeOn(from))) {
175	            person.gradeFrom(grade, from);
176	        }
177	        Person saved = people.saveAndFlush(person);
178	        audited("PERSON_EDITED", sheetId, user, saved, today, withTerms, withContact);
179	        rollups.audit(sheetId, user, before);
180	        return saved;
181	    }
