212	        List<Person> listed = new ArrayList<>(people.findBySheetIdOrderByPositionAscIdAsc(sheetId));
213	        int at = -1;
214	        for (int i = 0; i < listed.size(); i++) {
215	            if (listed.get(i).getId() == personId) {
216	                at = i;
217	            }
218	        }
219	        if (at < 0) {
220	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
221	        }
222	        int to = up ? at - 1 : at + 1;
223	        if (to < 0 || to >= listed.size()) {
224	            throw new ResponseStatusException(HttpStatus.CONFLICT,
225	                    up ? "The top person cannot move up." : "The bottom person cannot move down.");
226	        }
227	        java.util.Collections.swap(listed, at, to);
228	        for (int i = 0; i < listed.size(); i++) {
229	            Person each = listed.get(i);
230	            if (each.getPosition() != i + 1) {
231	                each.setPosition(i + 1);
232	                people.save(each);
233	            }
234	        }
235	        people.flush();
236	        Person moved = listed.get(to);
