432	    /**
433	     * The keys of the names and aliases in use on the other sheets of the sheet's tree: its ancestors,
434	     * its descendants and theirs, among the sheets that exist.
435	     */
436	    private Set<String> treeKeys(String sheetId) {
437	        List<String> tree = new ArrayList<>(sheetStore.ancestors(sheetId));
438	        tree.addAll(sheetStore.descendants(sheetId));
439	        tree.remove(sheetId);
440	        if (tree.isEmpty()) {
441	            return Set.of();
442	        }
443	        Set<String> keys = new HashSet<>(people.findNameKeysBySheetIdIn(tree));
444	        keys.addAll(people.findAliasKeysBySheetIdIn(tree));
445	        return keys;
446	    }
