378	        return tags == null ? java.util.List.of() : java.util.List.of(tags.split(","));
379	    }
380	
381	    /** Give the claim its tags (see {@link #tagsOf}); empty for none. */
382	    public void tag(java.util.List<String> tags) {
383	        this.tags = tags.isEmpty() ? null : String.join(",", tags);
384	        java.util.List<String> used = java.util.stream.Stream.concat(getTagsUsed().stream(), tags.stream())
385	                .distinct().sorted().toList();
386	        this.tagsUsed = used.isEmpty() ? null : String.join(",", used);
387	    }
388	
389	    /** Every tag the claim has ever carried, sorted; empty when none. */
390	    public java.util.List<String> getTagsUsed() {
391	        return tagsUsed == null ? java.util.List.of() : java.util.List.of(tagsUsed.split(","));
392	    }
393	
394	    /**
395	     * Tags as a comma separated text gives them: each trimmed and lower case, blanks and repeats
396	     * dropped, sorted.
397	     */
398	    public static java.util.List<String> tagsOf(String text) {
399	        if (text == null) {
400	            return java.util.List.of();
401	        }
402	        return java.util.Arrays.stream(text.split(","))
403	                .map((t) -> t.trim().toLowerCase(java.util.Locale.ROOT))
404	                .filter((t) -> !t.isEmpty())
405	                .distinct()
406	                .sorted()
407	                .toList();
408	    }
409	
410	    /** A reference as compared on a sheet, without regard to case; null for none. */
411	    public static String keyOf(String ref) {
412	        return ref == null ? null : ref.toLowerCase(java.util.Locale.ROOT);
413	    }
414	
415	    /** Whether the claim is a correction: its amount is below 0.00. */
416	    public boolean isCorrection() {
417	        return amount.signum() < 0;
418	    }
419	
420	    /** Change the claim's amount, date, note and the number it corrects. */
421	    public void change(BigDecimal amount, LocalDate date, String note, String corrects) {
422	        this.amount = amount;
423	        this.date = date;
424	        this.note = note;
425	        this.corrects = corrects;
426	    }
