446	    public void bind(BigDecimal due, boolean whole) {
447	        this.stated = true;
448	        this.statedDue = due;
449	        this.statedWhole = whole;
450	    }
451	
452	    /** Move the claim to a new date; its due-by, number and any bound figure are kept. */
453	    public void redate(LocalDate date) {
454	        this.date = date;
455	    }
