465	     * editor's lock. The caller gives it the other sheet's number.
466	     */
467	    public void transferTo(String sheetId) {
468	        this.sheetId = sheetId;
469	        refer(null);
470	        this.settleBatch = null;
471	        this.lockedBy = null;
