551	     * Split an amount off the claim: it keeps the rest of its amount and loses any figure a statement
552	     * bound it to. The new claim, OPEN with the split-off amount, the same date and note, names this
553	     * claim's number as the one it was split from; the caller numbers it and records who opened it.
554	     */
555	    public Claim split(BigDecimal off, int newTerms, LocalDate newDueBy) {
556	        Claim split = new Claim(sheetId, personId, off, date, newTerms, newDueBy, note, null);
557	        split.status = ClaimStatus.OPEN;
