578	    public void addProof(String kind) {
579	        switch (kind) {
580	            case "receipt" -> proofsReceipt++;
581	            case "photo" -> proofsPhoto++;
582	            default -> throw new IllegalArgumentException("No such proof kind: " + kind);
583	        }
584	        proofs++;
585	    }
