638	    public void addLine(String label, int qty, BigDecimal unit) {
639	        lines.add(new ClaimLine(label, qty, unit));
640	        this.amount = lines.stream().map(ClaimLine::total).reduce(BigDecimal.ZERO, BigDecimal::add)
