28	/**
29	 * A person's statements: taking one records their due-total on the sheet's today (or a date before it), binds each of
30	 * their counting claims to the due it shows then (late charge included), and leaves the rest unbound. A steward may
31	 * cancel the last one: the claims it bound are live again, and the person shows the one before it.
32	 */
33	@Service
34	public class StatementService {
35	
36	    /** Shown in place of a due-total when the grade has no rate. */
37	    private static final String NO_RATE = "n/a";
38	
39	    /** The person as stated, with all of their claims, newest first. */
40	    public record Stated(Person person, List<Claim> claims) {
41	    }
42	
43	    private final PersonRepository people;
44	    private final ClaimRepository claims;
45	    private final Dues dues;
46	    private final SheetHistory history;
47	    private final SheetService sheets;
48	    private final Rollups rollups;
49	    private final StatementRepository statements;
50	    private final RoleService roles;
51	    private final Audit audit;
52	    private final EntityManager entities;
53	
54	    public StatementService(PersonRepository people, ClaimRepository claims, Dues dues, SheetHistory history,
55	            SheetService sheets, Rollups rollups, StatementRepository statements, RoleService roles, Audit audit,
56	            EntityManager entities) {
57	        this.entities = entities;
58	        this.rollups = rollups;
59	        this.statements = statements;
60	        this.roles = roles;
61	        this.people = people;
62	        this.claims = claims;
63	        this.dues = dues;
64	        this.history = history;
65	        this.sheets = sheets;
66	        this.audit = audit;
67	    }
68	
69	    /**
70	     * Take a statement for a person on the sheet, as of a date on or before the sheet's today (null:
71	     * now). Their claims that counted at the end of that date are bound to the figures they had then,
72	     * every change made while the sheet's today was after it left out and that date standing in for
73	     * the sheet's today; every other claim of theirs is left unbound. Refused for a date after the
74	     * sheet's today, or one the sheet or the person was not yet kept on.
75	     */
76	    @Transactional
77	    public Stated take(String sheetId, String user, long personId, LocalDate asOf) {
78	        LocalDate today = sheets.today(sheetId);
79	        Person person = people.findByIdAndSheetId(personId, sheetId)
80	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
81	        if (asOf != null && asOf.isAfter(today)) {
82	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A statement cannot be taken as of a date after today.");
83	        }
84	        LocalDate day = asOf != null ? asOf : today;
85	        // On the sheet's today every change counts: the sheet as it stands now. Before it, as kept then.
86	        Person then;
87	        // Their claims as they stood then, by id.
88	        Map<Long, Claim> theirsThen = new LinkedHashMap<>();
89	        // Everyone's claims and people as they stood then, for the parts of others' claims shared with them.
90	        Iterable<Claim> allThen;
91	        Map<Long, Person> peopleThen = new HashMap<>();
92	        Dues.Basis basis;
93	        Sheet sheet;
94	        if (day.equals(today)) {
95	            then = person;
96	            claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).forEach(c -> theirsThen.put(c.getId(), c));
97	            allThen = claims.findBySheetIdOrderByIdDesc(sheetId);
98	            people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> peopleThen.put(p.getId(), p));
99	            basis = dues.live(sheetId);
100	            sheet = sheets.load(sheetId);
101	        } else {
102	            SheetHistory.AsOf kept = history.at(sheetId, day).orElseThrow(() -> notYet(day));
103	            then = kept.people().get(personId);
104	            if (then == null) {
105	                throw notYet(day);
106	            }
107	            kept.claims().forEach((id, c) -> {
108	                if (c.getPersonId() == personId) {
109	                    theirsThen.put(id, c);
110	                }
111	            });
112	            allThen = kept.claims().values();
113	            peopleThen.putAll(kept.people());
114	            basis = kept.basis();
115	            sheet = kept.sheet();
116	        }
117	        Rollups.Rollup before = rollups.take(sheetId);
118	        Map<Long, BigDecimal> bound = new HashMap<>();
119	        BigDecimal total = BigDecimal.ZERO.setScale(2);
120	        boolean figured = false;
121	        int counted = 0;
122	        List<LocalDate> countingDates = new ArrayList<>();
123	        for (Map.Entry<Long, Claim> entry : theirsThen.entrySet()) {
124	            Claim claim = entry.getValue();
125	            // As in the live totals: an OPEN or PENDING claim of a person whose retirement date is reached,
126	            // and not bound, is left out, as is a claim deferred on the day; a held one counts.
127	            if (!then.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(day), day)) {
128	                continue;
129	            }
130	            // The statement binds the due as shown, late charge and floor included: a figure an earlier
131	            // statement bound stays as it is.
132	            BigDecimal due = dues.due(claim, then.gradeOn(claim.getDate()), basis);
133	            figured |= due != null;
134	            bound.put(entry.getKey(), due);
135	            counted++;
136	            countingDates.add(claim.getDate());
137	            if (due != null) {
138	                // As in the live totals: a shared claim counts its figure less its holders' parts.
139	                total = total.add(claim.getShares().isEmpty() ? due : due.subtract(claim.sharedParts(share -> {
140	                    Person holder = peopleThen.get(share.getPersonId());
141	                    return dues.part(claim, share, holder == null ? null : holder.gradeOn(claim.getDate()), due, basis);
142	                })));
143	            }
144	        }
145	        // As in the live totals: their parts of others' shared claims that count for their own person.
146	        for (Claim claim : allThen) {
147	            Person owner = peopleThen.get(claim.getPersonId());
148	            if (claim.getPersonId() == personId || owner == null || !claim.getStatus().counts()
149	                    || claim.getShares().stream().noneMatch(share -> share.getPersonId() == personId)
150	                    || !owner.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(day), day)) {
151	                continue;
152	            }
153	            BigDecimal figure = dues.due(claim, owner.gradeOn(claim.getDate()), basis);
154	            if (figure == null) {
155	                continue;
156	            }
157	            for (var share : claim.getShares()) {
158	                BigDecimal part = share.getPersonId() == personId
159	                        ? dues.part(claim, share, then.gradeOn(claim.getDate()), figure, basis) : null;
160	                if (part != null) {
161	                    figured = true;
162	                    total = total.add(part);
163	                }
164	            }
165	        }
166	        // As on the screen: n/a when the grade in force on the day has no rate, unless a claim has a figure.
167	        if (basis.rateInForce(then.gradeOn(day), day).isEmpty() && !figured) {
168	            total = null;
169	        }
170	        // A due-total is at most their cap: the one in force on their latest counting claim's date. The
171	        // claims they have now are bound by id.
172	        total = sheet.capped(total, countingDates);
173	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
174	        for (Claim claim : theirs) {
175	            if (bound.containsKey(claim.getId())) {
176	                claim.bind(bound.get(claim.getId()));
177	            } else {
178	                claim.unbind();
179	            }
180	        }
181	        person.stated(total, day);
182	        Person saved = people.saveAndFlush(person);
183	        statements.saveAndFlush(new Statement(sheetId, saved.getId(), saved.getStatementCount(), total, day));
184	        // The person shows the statement just taken among their lines.
185	        entities.refresh(saved);
186	        List<Claim> stated = claims.saveAllAndFlush(theirs);
187	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
188	                + " due-total=" + (total != null ? total.toPlainString() : NO_RATE) + " claims=" + counted
189	                + (asOf != null ? " asof=" + asOf : ""));
190	        rollups.audit(sheetId, user, before);
191	        return new Stated(saved, stated);
192	    }
