194	    /**
195	     * Hand a person's statements to another they join (on the other's sheet): the other's count
196	     * becomes their own plus theirs, numbered with theirs first, and the other's last statement stays
197	     * the other's, or, having none, becomes theirs. The caller saves the other.
198	     */
199	    public void handOver(String fromSheetId, Person from, Person into) {
200	        int moved = from.getStatementCount();
201	        List<Statement> intos = statements.findBySheetIdAndPersonIdOrderBySeqDesc(into.getSheetId(), into.getId());
202	        // The other's own are numbered after theirs, the last first so no two share a number.
203	        for (Statement statement : intos) {
204	            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq() + moved);
205	            statements.saveAndFlush(statement);
206	        }
207	        for (Statement statement : statements.findBySheetIdAndPersonIdOrderBySeqDesc(fromSheetId, from.getId())) {
208	            statement.moveTo(into.getSheetId(), into.getId(), statement.getSeq());
209	            statements.saveAndFlush(statement);
210	        }
211	        into.absorbStatements(from);
212	    }
