227	    /** Refused: the sheet, or the person, was not yet kept at the end of that date. */
228	    private static ResponseStatusException notYet(LocalDate day) {
229	        return new ResponseStatusException(HttpStatus.CONFLICT, "The person was not on the sheet on " + day + ".");
230	    }
