232	    /**
233	     * Cancel a person's last statement: the claims it bound are live again (a figure an earlier
234	     * statement bound is not restored), and the person shows the statement before it, or none. Only a
235	     * steward cancels; refused when the person has no statement.
236	     */
237	    @Transactional
238	    public Stated cancel(String sheetId, String user, long personId) {
239	        sheets.lock(sheetId);
240	        Person person = people.findByIdAndSheetId(personId, sheetId)
241	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
242	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
243	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward cancels a statement.");
244	        }
245	        if (person.getStatementCount() == 0) {
246	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " has no statement to cancel.");
247	        }
248	        Rollups.Rollup before = rollups.take(sheetId);
249	        BigDecimal cancelled = person.getStatementTotal();
250	        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderBySeqDesc(sheetId, personId);
251	        if (!taken.isEmpty() && taken.get(0).getSeq() == person.getStatementCount()) {
252	            statements.delete(taken.remove(0));
253	        }
254	        // The one before it, when it was recorded.
255	        Statement previous = taken.isEmpty() || taken.get(0).getSeq() != person.getStatementCount() - 1
256	                ? null : taken.get(0);
257	        person.unstated(previous == null ? null : previous.getTotal(), previous == null ? null : previous.getTakenOn());
258	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
259	        theirs.forEach(Claim::unbind);
260	        Person saved = people.saveAndFlush(person);
261	        List<Claim> live = claims.saveAllAndFlush(theirs);
262	        // The person no longer shows the cancelled statement among their lines.
263	        entities.refresh(saved);
264	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
265	                + " due-total=" + (cancelled != null ? cancelled.toPlainString() : NO_RATE));
266	        rollups.audit(sheetId, user, before);
267	        return new Stated(saved, live);
268	    }
