2	
3	import java.util.ArrayList;
4	import java.util.HashSet;
5	import java.util.List;
6	import java.util.Set;
7	import net.officefloor.hq.app.grade.GradeService;
8	import net.officefloor.hq.app.sheet.SheetService;
9	import org.springframework.http.HttpStatus;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	import org.springframework.web.server.ResponseStatusException;
13	
14	/**
15	 * The import box: lines of name,grade,terms,contact each add a person, in order, as the person form
16	 * would; a line whose name matches a person on the sheet, by name or alias as names are compared, instead
17	 * updates them as the person form would: their grade recorded from the sheet's today, and their terms and
18	 * contact set when the line gives them. A blank grade is the sheet's default grade. The terms and the contact may be absent or blank. Every line is
19	 * held to the person form's rules, and a name, person or contact repeated within the paste is refused; it
20	 * is one change, so when any line is refused nothing is imported and nothing is recorded.
21	 */
22	@Service
23	public class ImportService {
24	
25	    /** The longest name or contact the person form takes. */
26	    private static final int TEXT_MAX = 200;
27	
28	    /** The most days of terms the person form takes. */
29	    private static final int TERMS_MAX = 36500;
30	
31	    /** The most lines one import takes. */
32	    static final int LINES_MAX = 1000;
33	
34	    /** A line read from the paste, checked against the form's rules. */
35	    private record Line(String name, String grade, Integer terms, String contact) {
36	    }
37	
38	    /** The people an import added and those it updated, each in the order of their lines. */
39	    public record Imported(List<Person> added, List<Person> updated) {
40	    }
41	
42	    private final PersonService people;
43	    private final PersonRepository store;
44	    private final SheetService sheets;
45	
46	    public ImportService(PersonService people, PersonRepository store, SheetService sheets) {
47	        this.people = people;
48	        this.store = store;
49	        this.sheets = sheets;
50	    }
51	
52	    /** Add or update a person per line of the text, in order; refused as a whole when any line is refused. */
53	    @Transactional
54	    public Imported importPeople(String sheetId, String user, String text) {
55	        List<Line> lines = new ArrayList<>();
56	        Set<String> names = new HashSet<>();
57	        Set<String> contacts = new HashSet<>();
58	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
59	        for (int i = 0; i < raw.length; i++) {
60	            if (raw[i].isBlank()) {
61	                continue;
62	            }
63	            Line line = line(i + 1, raw[i]);
64	            if (!names.add(Person.keyOf(line.name()))) {
65	                throw refused("Line " + (i + 1) + ": " + line.name() + " is named more than once.");
66	            }
67	            String contact = Person.contactOf(line.contact());
68	            if (contact != null && !contacts.add(contact)) {
69	                throw refused("Line " + (i + 1) + ": the contact " + contact + " is given more than once.");
70	            }
71	            lines.add(line);
72	        }
73	        if (lines.isEmpty()) {
74	            throw refused("Paste at least one line of name,grade,terms,contact.");
75	        }
76	        if (lines.size() > LINES_MAX) {
77	            throw refused("Paste at most " + LINES_MAX + " lines at once.");
78	        }
79	        List<Person> added = new ArrayList<>();
80	        List<Person> updated = new ArrayList<>();
81	        Set<Long> matched = new HashSet<>();
82	        for (int i = 0; i < lines.size(); i++) {
83	            String grade = lines.get(i).grade();
84	            if (grade != null) {
85	                try {
86	                    people.requireGradeOpen(sheetId, grade);
87	                } catch (ResponseStatusException retired) {
88	                    throw refused("Line " + (i + 1) + ": the grade " + grade + " is retired.");
89	                }
90	            }
91	        }
92	        String defaultGrade = sheets.defaultGrade(sheetId);
93	        int number = 0;
94	        for (Line line : lines) {
95	            number++;
96	            Person existing = store.findBySheetIdAndName(sheetId, line.name()).orElse(null);
97	            if (existing == null) {
98	                added.add(people.add(sheetId, user, line.name(), line.grade() != null ? line.grade() : defaultGrade, line.terms(), line.contact()));
99	                continue;
100	            }
101	            if (!matched.add(existing.getId())) {
102	                throw refused("Line " + number + ": " + existing.getName() + " is named more than once.");
103	            }
104	            boolean termsGiven = line.terms() != null;
105	            boolean contactGiven = line.contact() != null;
106	            updated.add(people.edit(sheetId, user, existing.getId(), existing.getVersion(), existing.getName(),
107	                    line.grade() != null ? line.grade() : defaultGrade, null, termsGiven ? line.terms() : existing.getTerms(),
108	                    contactGiven ? line.contact() : existing.getContact(), termsGiven, contactGiven));
109	        }
110	        return new Imported(added, updated);
111	    }
112	
113	    private Line line(int number, String text) {
114	        String[] fields = text.split(",", -1);
115	        if (fields.length < 2) {
116	            throw refused("Line " + number + " needs at least a name and a grade.");
117	        }
118	        if (fields.length > 4) {
119	            throw refused("Line " + number + " has more than name,grade,terms,contact.");
120	        }
121	        String name = fields[0].trim();
122	        if (name.isEmpty()) {
123	            throw refused("Line " + number + " has no name.");
124	        }
125	        if (name.length() > TEXT_MAX) {
126	            throw refused("Line " + number + ": the name is longer than " + TEXT_MAX + " characters.");
127	        }
128	        String grade = fields[1].trim();
129	        if (!grade.isEmpty() && !grade.matches(GradeService.CODE)) {
130	            throw refused("Line " + number + ": the grade must be one to three capital letters or blank.");
131	        }
132	        Integer terms = null;
133	        String days = fields.length > 2 ? fields[2].trim() : "";
134	        if (!days.isEmpty()) {
135	            if (!days.matches("\\d{1,9}") || Integer.parseInt(days) > TERMS_MAX) {
136	                throw refused("Line " + number + ": the terms must be a whole number of days up to " + TERMS_MAX + ".");
137	            }
138	            terms = Integer.parseInt(days);
139	        }
140	        String contact = fields.length > 3 ? fields[3].trim() : "";
141	        if (contact.length() > TEXT_MAX) {
142	            throw refused("Line " + number + ": the contact is longer than " + TEXT_MAX + " characters.");
143	        }
144	        return new Line(name, grade.isEmpty() ? null : grade, terms, contact.isEmpty() ? null : contact);
145	    }
146	
147	    private static ResponseStatusException refused(String reason) {
148	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
149	    }
150	}
