36	/**
37	 * The sheet as it stood at the end of past dates. Every change is made on the sheet's today, so as the
38	 * sheet's today moves on from a date, everything its figures are read from (its settings, rates,
39	 * people and claims) is kept as it stands: what was changed while the sheet's today was on or before
40	 * that date, and nothing changed later.
41	 */
42	@Service
43	public class SheetHistory {
44	
45	    /**
46	     * A sheet's figures-bearing state, as kept (its pot null in states kept before the pot was, its policy
47	     * versions null in states kept before they were).
48	     */
49	    record State(LocalDate policyDate, List<SettingState> settings, List<RateState> rates,
50	            List<PersonState> people, List<ClaimState> claims, PotState pot,
51	            List<PolicyVersionState> policyVersions) {
52	    }
53	
54	    record PolicyVersionState(int number, String key, LocalDate from, String value) {
55	    }
56	
57	    /** The sheet's pot as kept; its value null for none. */
58	    record PotState(BigDecimal value) {
59	    }
60	
61	    record SettingState(String key, LocalDate from, String value) {
62	    }
63	
64	    /**
65	     * A rate as kept: where it was saved in the order claims are added when forward-only, and its older
66	     * versions newest first (both null in states kept before forward-only rates).
67	     */
68	    record RateState(String grade, LocalDate from, LocalDate to, BigDecimal pct, Long forwardAfter,
69	            List<RateVersionState> older) {
70	    }
71	
72	    record RateVersionState(int version, BigDecimal pct, LocalDate to, Long forwardAfter) {
73	    }
74	
75	    record GradeState(LocalDate from, String grade) {
76	    }
77	
78	    record HoldState(LocalDate from, LocalDate to) {
79	    }
80	
81	    record TermsState(LocalDate from, Integer terms) {
82	    }
83	
84	    record PersonState(long id, String name, String grade, List<GradeState> grades, Integer terms,
85	            List<HoldState> holds, LocalDate retiredFrom, String contact, List<String> aliases,
86	            List<RetirementState> retirements, List<TermsState> termsFrom) {
87	    }
88	
89	    record RetirementState(LocalDate from, LocalDate to) {
90	    }
91	
92	    record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, ClaimStatus status,
93	            String number, BigDecimal settledDue, boolean stated, BigDecimal statedDue, String corrects,
94	            LocalDate deferredUntil, Long added, Boolean waived, Boolean statedWhole, Boolean held,
95	            List<ShareState> shares) {
96	    }
97	
98	    /** A share of a claim as kept (none in states kept before claims were shared). */
99	    record ShareState(long personId, BigDecimal share) {
100	    }
101	
102	    /**
103	     * The sheet as it stood at the end of a date, held in no store: the sheet with that date as its
104	     * today, its people by id and its claims by id, newest first, and the basis their figures are read
105	     * against.
106	     */
107	    public record AsOf(Sheet sheet, Map<Long, Person> people, Map<Long, Claim> claims, Dues.Basis basis) {
108	    }
109	
110	    /**
111	     * What the screen is told about the sheet as it stood at the end of a date: its people, claims
112	     * (newest first), rates, periods and pools, and whether it was archived (its pools null in views kept
113	     * before pools were).
114	     */
115	    public record Views(boolean archived, List<PersonView> people, List<ClaimView> claims, List<RateView> rates,
116	            List<PeriodView> periods, List<PoolView> pools) {
117	
118	        /** The sheet before anything was kept for it. */
119	        static final Views EMPTY = new Views(false, List.of(), List.of(), List.of(), List.of(), List.of());
120	    }
121	
122	    /**
123	     * What a pool's cuts at the end of a period are worked out from: the period, whether its to-date is
124	     * the sheet's today (the sheet as it stands then, not told here), and else the sheet's pot (null for
125	     * none), people and pools as they stood at the end of its to-date.
126	     */
127	    public record PeriodPools(String period, LocalDate to, boolean current, String pot, List<PersonView> people,
128	            List<PoolView> pools) {
129	    }
130	
131	    /**
132	     * What a closed or soft-closed period's pool cuts are worked out from, fixed when it was closed: the
133	     * sheet's today then, its pot (null for none), people and pools as they stood.
134	     */
135	    record FixedCuts(LocalDate today, String pot, List<PersonView> people, List<PoolView> pools) {
136	    }
