138	    private final SheetSnapshotRepository snapshots;
139	    private final SheetRepository sheets;
140	    private final RateRepository rates;
141	    private final PersonRepository people;
142	    private final ClaimRepository claims;
143	    private final PeriodRepository periods;
144	    private final PoolService pools;
145	    private final JsonMapper json;
146	
147	    public SheetHistory(SheetSnapshotRepository snapshots, SheetRepository sheets, RateRepository rates,
148	            PersonRepository people, ClaimRepository claims, PeriodRepository periods, PoolService pools,
149	            JsonMapper json) {
150	        this.pools = pools;
151	        this.snapshots = snapshots;
152	        this.sheets = sheets;
153	        this.rates = rates;
154	        this.people = people;
155	        this.claims = claims;
156	        this.periods = periods;
157	        this.json = json;
158	    }
159	
160	    /** The sheet's today moves on: keep the sheet as it stands, as it was at the end of the date it leaves. */
161	    @EventListener
162	    @Transactional
163	    public void todayLeaving(TodayLeaving leaving) {
164	        String sheetId = leaving.sheetId();
165	        Sheet sheet = sheets.findById(sheetId).orElseThrow();
166	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
167	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
168	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
169	        State state = new State(sheet.getPolicyDate(),
170	                sheet.getDated().stream().map(d -> new SettingState(d.getKey(), d.getFromDate(), d.getValue())).toList(),
171	                sheetRates.stream().map(SheetHistory::kept).toList(),
172	                sheetPeople.stream().map(SheetHistory::kept).toList(),
173	                sheetClaims.stream().map(SheetHistory::kept).toList(), new PotState(sheet.getPot()),
174	                sheet.getPolicyVersions().stream()
175	                        .map(v -> new PolicyVersionState(v.getNumber(), v.getKey(), v.getFromDate(), v.getValue())).toList());
176	        Views views = new Views(sheet.isArchived(), sheetPeople.stream().map(PersonView::of).toList(),
177	                sheetClaims.stream().map(ClaimView::of).toList(), sheetRates.stream().map(RateView::of).toList(),
178	                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().map(PeriodView::of).toList(),
179	                pools.list(sheetId).stream().map(PoolView::of).toList());
180	        snapshots.save(new SheetSnapshot(sheetId, leaving.today(), json.writeValueAsString(state),
181	                json.writeValueAsString(views)));
182	    }
183	
184	    /**
185	     * What a screen showing the sheet as of a date before its today is told: the views kept for the
186	     * last snapshot on or before that date, or an empty sheet when none was kept by then. Empty when
187	     * no as-of date is set (null), or it is on or after the sheet's today: every change made so far
188	     * counts then, and the screen is told the sheet as it stands.
189	     */
190	    @Transactional(readOnly = true)
191	    public Optional<Views> views(String sheetId, LocalDate asOf) {
192	        if (!past(sheetId, asOf)) {
193	            return Optional.empty();
194	        }
195	        return Optional.of(snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByIdDesc(sheetId, asOf)
196	                .map(snapshot -> snapshot.getViews() == null ? Views.EMPTY
197	                        : json.readValue(snapshot.getViews(), Views.class))
198	                .orElse(Views.EMPTY));
199	    }
200	
201	    /**
202	     * The sheet a screen showing it as of a date (null: none) is told about, held in no store: with no
203	     * as-of date the sheet as it stands; else the sheet with the as-of date as its today, its settings
204	     * as they stood at the end of that date (as they stand when it is on or after the sheet's today).
205	     */
206	    @Transactional(readOnly = true)
207	    public Sheet sheet(Sheet now, LocalDate asOf) {
208	        if (asOf == null) {
209	            return now;
210	        }
211	        if (!asOf.isBefore(now.getToday())) {
212	            return now.asOf(asOf, now.getDated(), now.getPolicyDate());
213	        }
214	        Sheet then = at(now.getId(), asOf).map(AsOf::sheet)
215	                .orElseGet(() -> now.asOf(asOf, List.of(), null, List.of()));
216	        then.setArchived(views(now.getId(), asOf).orElse(Views.EMPTY).archived());
217	        return then;
218	    }
219	
220	    /**
221	     * What a pool's cuts are worked out from as the sheet stands now, with today as the sheet's today, as
222	     * JSON: fixed for a period as it is closed or soft-closed.
223	     */
224	    @Transactional(readOnly = true)
225	    public String cutsNow(String sheetId, LocalDate today) {
226	        Sheet sheet = sheets.findById(sheetId).orElseThrow();
227	        return json.writeValueAsString(new FixedCuts(today,
228	                sheet.getPot() == null ? null : sheet.getPot().toPlainString(),
229	                people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream().map(PersonView::of).toList(),
230	                pools.list(sheetId).stream().map(PoolView::of).toList()));
231	    }
232	
233	    /**
234	     * Each period whose to-date is on or before the sheet's today, or that is closed or soft-closed, in
235	     * from-date order, with what its pools' cuts are worked out from: for a closed or soft-closed period,
236	     * the today, pot, people and pools fixed when it was closed, its cuts as they stood then; else for a
237	     * to-date before the sheet's today, the pot, people and pools kept for the last snapshot on or before
238	     * it (none when nothing was kept by then).
239	     */
240	    @Transactional(readOnly = true)
241	    public List<PeriodPools> periodPools(String sheetId) {
242	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
243	        if (today == null) {
244	            return List.of();
245	        }
246	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
247	                .filter(p -> !p.getToDate().isAfter(today) || (p.isFixed() && p.getCuts() != null))
248	                .map(p -> {
249	                    if (p.isFixed() && p.getCuts() != null) {
250	                        FixedCuts fixed = json.readValue(p.getCuts(), FixedCuts.class);
251	                        return new PeriodPools(p.getName(), fixed.today(), false, fixed.pot(), fixed.people(),
252	                                fixed.pools());
253	                    }
254	                    if (p.getToDate().equals(today)) {
255	                        return new PeriodPools(p.getName(), p.getToDate(), true, null, List.of(), List.of());
256	                    }
257	                    return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByIdDesc(sheetId, p.getToDate())
258	                            .map(snapshot -> {
259	                                State state = json.readValue(snapshot.getState(), State.class);
260	                                Views views = snapshot.getViews() == null ? Views.EMPTY
261	                                        : json.readValue(snapshot.getViews(), Views.class);
262	                                BigDecimal pot = state.pot() == null ? null : state.pot().value();
263	                                return new PeriodPools(p.getName(), p.getToDate(), false,
264	                                        pot == null ? null : pot.toPlainString(), views.people(),
265	                                        views.pools() == null ? List.of() : views.pools());
266	                            })
267	                            .orElseGet(() -> new PeriodPools(p.getName(), p.getToDate(), false, null, List.of(),
268	                                    List.of()));
269	                })
270	                .toList();
271	    }
272	
273	    /** Whether an as-of date (null: none) is before the sheet's today. */
274	    private boolean past(String sheetId, LocalDate asOf) {
275	        return asOf != null && sheets.findById(sheetId).map(s -> asOf.isBefore(s.getToday())).orElse(false);
276	    }
277	
278	    /**
279	     * The sheet as it stood at the end of a date before its today; empty when nothing was kept for
280	     * it on or before that date.
281	     */
282	    @Transactional(readOnly = true)
283	    public Optional<AsOf> at(String sheetId, LocalDate day) {
284	        Sheet now = sheets.findById(sheetId).orElse(null);
285	        if (now == null) {
286	            return Optional.empty();
287	        }
288	        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByIdDesc(sheetId, day)
289	                .map(snapshot -> restored(now, day, json.readValue(snapshot.getState(), State.class),
290	                        inherited(sheetId, day)));
291	    }
292	
293	    /**
294	     * The rates of the sheet's ancestors, nearest first, up to {@link Dues#PARENT_LEVELS}, each as it
295	     * stood at the end of a date (null: as it stands): an ancestor's rates as kept for the last snapshot
296	     * on or before that date when it is before the ancestor's today (none when nothing was kept by
297	     * then), else as they stand; then, for a cloned sheet, those of the sheet it was cloned from, its
298	     * ancestors and its source, and so on, each likewise. The parent itself is not dated: the chain is
299	     * the one set now.
300	     */
301	    @Transactional(readOnly = true)
302	    public List<List<Rate>> inherited(String sheetId, LocalDate day) {
303	        return sheets.rateSources(sheetId, Dues.PARENT_LEVELS).stream()
304	                .map(ancestor -> past(ancestor, day) ? keptRates(ancestor, day)
305	                        : rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(ancestor))
306	                .toList();
307	    }
308	
309	    /** A sheet's rates as kept for the last snapshot on or before a date; none when nothing was kept by then. */
310	    private List<Rate> keptRates(String sheetId, LocalDate day) {
311	        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByIdDesc(sheetId, day)
312	                .map(snapshot -> rates(sheetId, json.readValue(snapshot.getState(), State.class)))
313	                .orElse(List.of());
314	    }
315	
316	    private static AsOf restored(Sheet now, LocalDate day, State state, List<List<Rate>> inherited) {
317	        Sheet sheet = now.asOf(day,
318	                state.settings().stream().map(s -> new DatedSetting(s.key(), s.from(), s.value())).toList(),
319	                state.policyDate(), state.policyVersions() == null ? List.of()
320	                        : state.policyVersions().stream()
321	                                .map(v -> new PolicyVersion(v.number(), v.key(), v.from(), v.value())).toList());
322	        if (state.pot() != null) {
323	            sheet.setPot(state.pot().value());
324	        }
325	        List<Rate> rates = rates(now.getId(), state);
326	        Map<Long, Person> people = new LinkedHashMap<>();
327	        for (PersonState p : state.people()) {
328	            Person person = new Person(now.getId(), p.name(), p.grade(), p.terms(), p.contact());
329	            p.grades().forEach(g -> person.gradeFrom(g.grade(), g.from()));
330	            if (p.termsFrom() != null) {
331	                p.termsFrom().forEach(t -> person.termsFrom(t.terms(), t.from()));
332	            }
333	            p.holds().forEach(h -> person.hold(h.from(), h.to()));
334	            if (p.aliases() != null) {
335	                p.aliases().forEach(person::addAlias);
336	            }
337	            if (p.retirements() != null) {
338	                p.retirements().forEach(r -> {
339	                    person.retire(r.from());
340	                    person.unretire(r.to());
341	                });
342	            }
343	            if (p.retiredFrom() != null) {
344	                person.retire(p.retiredFrom());
345	            }
346	            people.put(p.id(), person);
347	        }
348	        Map<Long, Claim> claims = new LinkedHashMap<>();
349	        for (ClaimState c : state.claims()) {
350	            Claim claim = new Claim(now.getId(), c.personId(), c.amount(), c.date(), 0, c.dueBy(), "", c.corrects());
351	            claim.become(c.status());
352	            claim.number(c.number());
353	            claim.settleDue(c.settledDue());
354	            if (c.stated()) {
355	                claim.bind(c.statedDue(), Boolean.TRUE.equals(c.statedWhole()));
356	            }
357	            claim.defer(c.deferredUntil());
358	            claim.keepAdded(c.added());
359	            if (Boolean.TRUE.equals(c.waived())) {
360	                claim.waive();
361	            }
362	            claim.hold(Boolean.TRUE.equals(c.held()));
363	            if (c.shares() != null) {
364	                c.shares().forEach(sh -> claim.share(sh.personId(), sh.share()));
365	            }
366	            claims.put(c.id(), claim);
367	        }
368	        Dues.Basis basis = new Dues.Basis(sheet, rates, inherited, correction -> claims.values().stream()
369	                .filter(c -> Objects.equals(c.getPersonId(), correction.getPersonId())
370	                        && Objects.equals(c.getNumber(), correction.getCorrects()))
371	                .findFirst());
372	        return new AsOf(sheet, people, claims, basis);
373	    }
374	
375	    /** The rates kept in a sheet's state, held in no store. */
376	    private static List<Rate> rates(String sheetId, State state) {
377	        return state.rates().stream().map(r -> {
378	            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.pct());
379	            rate.setToDate(r.to());
380	            rate.setForwardAfter(r.forwardAfter());
381	            if (r.older() != null) {
382	                rate.keepOlder(r.older().stream()
383	                        .map(v -> new RateVersion(null, v.version(), v.pct(), v.to(), v.forwardAfter())).toList());
384	            }
385	            return rate;
386	        }).toList();
387	    }
388	
389	    private static PersonState kept(Person p) {
390	        return new PersonState(p.getId(), p.getName(), p.getGrade(),
391	                p.getGradesFrom().entrySet().stream().map(e -> new GradeState(e.getKey(), e.getValue())).toList(),
392	                p.getTerms(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
393	                p.getRetiredFrom(), p.getContact(), p.getAliases(),
394	                p.getRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList(),
395	                p.getTermsFrom().entrySet().stream().map(e -> new TermsState(e.getKey(), e.getValue())).toList());
396	    }
397	
398	    private static RateState kept(Rate r) {
399	        return new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getPct(), r.getForwardAfter(),
400	                r.getOlder().stream().map(v -> new RateVersionState(v.getVersion(), v.getPct(), v.getToDate(),
401	                        v.getForwardAfter())).toList());
402	    }
403	
404	    private static ClaimState kept(Claim c) {
405	        return new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(), c.getDueBy(), c.getStatus(),
406	                c.getNumber(), c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getCorrects(), c.getDeferredUntil(), c.getAdded(),
407	                c.isWaived(), c.isStatedWhole(), c.isHeld(),
408	                c.getShares().stream().map(sh -> new ShareState(sh.getPersonId(), sh.getShare())).toList());
409	    }
410	}
