1	package net.officefloor.hq.app.history;
2	
3	import jakarta.servlet.http.HttpServletRequest;
4	import jakarta.servlet.http.HttpServletResponse;
5	import java.time.LocalDate;
6	import java.time.format.DateTimeParseException;
7	import org.springframework.context.annotation.Configuration;
8	import org.springframework.http.HttpMethod;
9	import org.springframework.http.HttpStatus;
10	import org.springframework.web.server.ResponseStatusException;
11	import org.springframework.web.servlet.HandlerInterceptor;
12	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
13	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
14	
15	/**
16	 * The as-of date a user's screen shows the sheet as of, sent in the {@link #HEADER} header (yyyy-mm-dd)
17	 * on every request while it is set. Every change asked for while it is set is refused: any request
18	 * other than a read, or the loading of the sheet, is turned away before it reaches its handler, so it
19	 * writes nothing and audits nothing.
20	 */
21	@Configuration
22	public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {
23	
24	    public static final String HEADER = "X-As-Of";
25	
26	    /** The as-of date from the header's value; null when none is set. */
27	    public static LocalDate date(String header) {
28	        String text = header == null ? "" : header.trim();
29	        try {
30	            return text.isEmpty() ? null : LocalDate.parse(text);
31	        } catch (DateTimeParseException e) {
32	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not an as-of date: " + text);
33	        }
34	    }
35	
36	    @Override
37	    public void addInterceptors(InterceptorRegistry registry) {
38	        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load");
39	    }
40	
41	    @Override
