8	/**
9	 * The preview date a user's screen shows the sheet's figures on, sent in the {@link #HEADER} header
10	 * (yyyy-mm-dd) on every request while it is set. Reads of figures take it as the sheet's today, over the
11	 * sheet's current records; every change ignores it and uses the sheet's real today, and nothing is kept,
12	 * scored or closed for it, as the sheet's today in the store does not move.
13	 */
14	public final class PreviewDate {
15	
16	    public static final String HEADER = "X-Preview";
17	
18	    private PreviewDate() {
19	    }
20	
21	    /** The preview date from the header's value; null when none is set. */
22	    public static LocalDate date(String header) {
23	        String text = header == null ? "" : header.trim();
24	        try {
25	            return text.isEmpty() ? null : LocalDate.parse(text);
26	        } catch (DateTimeParseException e) {
27	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a preview date: " + text);
28	        }
29	    }
30	
31	    /** The day figures are read on: none while an as-of date is set (it decides), else the preview date. */
32	    public static LocalDate date(String asOfHeader, String previewHeader) {
33	        return AsOfGuard.date(asOfHeader) != null ? null : date(previewHeader);
34	    }
35	}
