322	import org.springframework.http.HttpStatus;
323	import org.springframework.stereotype.Service;
324	import org.springframework.transaction.annotation.Transactional;
325	import org.springframework.web.server.ResponseStatusException;
326	
327	/**
328	 * Users watching people on a sheet: each user starts and stops watching a person for themselves, and
329	 * every watcher of a person is notified when one of the person's claims is settled, approved or
330	 * re-settled.
331	 */
332	@Service
333	public class WatchService {
334	
335	    private final WatchRepository watches;
336	    private final PersonRepository people;
337	    private final Audit audit;
338	
339	    public WatchService(WatchRepository watches, PersonRepository people, Audit audit) {
340	        this.watches = watches;
341	        this.people = people;
342	        this.audit = audit;
343	    }
344	
345	    /** The ids of the people on the sheet the user watches, in ascending order. */
346	    @Transactional(readOnly = true)
347	    public List<Long> watched(String sheetId, String user) {
348	        return watches.findBySheetIdAndUser(sheetId, user).stream().map(Watch::getPersonId).sorted().toList();
349	    }
350	
351	    /** Start watching a person as the user; refused when they already watch them. */
352	    @Transactional
353	    public void watch(String sheetId, String user, long personId) {
354	        Person person = person(sheetId, personId);
355	        if (watches.findBySheetIdAndPersonIdAndUser(sheetId, personId, user).isPresent()) {
356	            throw new ResponseStatusException(HttpStatus.CONFLICT, "You already watch " + person.getName() + ".");
357	        }
358	        watches.saveAndFlush(new Watch(sheetId, personId, user));
359	        audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
360	    }
361	
362	    /** Stop watching a person as the user; refused when they do not watch them. */
363	    @Transactional
364	    public void unwatch(String sheetId, String user, long personId) {
365	        Person person = person(sheetId, personId);
366	        Watch watch = watches.findBySheetIdAndPersonIdAndUser(sheetId, personId, user)
367	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
368	                        "You do not watch " + person.getName() + "."));
369	        watches.delete(watch);
370	        watches.flush();
371	        audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
372	    }
373	
374	    /**
375	     * Notify each user watching the person that their claim of this number was settled, approved or
376	     * re-settled, in the order they started watching, once the change is committed.
377	     */
378	    public void notifyWatchers(String sheetId, String user, Person person, String number) {
379	        for (Watch watch : watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, person.getId())) {
380	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
381	                    + " person=" + person.getName() + " number=" + number);
382	        }
383	    }
384	
385	    private Person person(String sheetId, long personId) {
386	        return people.findByIdAndSheetId(personId, sheetId)
387	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
388	    }
389	}
