 73	    /**
 74	     * Merge a person into another on the sheet: the person merged into, as the store holds them after.
 75	     * Refused unless the user is a steward, for the person themselves, and when either is retired.
 76	     */
 77	    @Transactional
 78	    public Person merge(String sheetId, String user, long personId, long intoId) {
 79	        sheets.lock(sheetId);
 80	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
 81	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward merges people.");
 82	        }
 83	        Person from = people.findByIdAndSheetId(personId, sheetId)
 84	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
 85	        Person into = people.findByIdAndSheetId(intoId, sheetId)
 86	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
 87	        if (from.getId().equals(into.getId())) {
 88	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
 89	        }
 90	        if (from.getRetiredFrom() != null || into.getRetiredFrom() != null) {
 91	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
 92	        }
 93	        Rollups.Rollup before = rollups.take(sheetId);
 94	
 95	        // Their claims, in the order they were added, move to the other, still bound as they were.
 96	        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, from.getId()).stream()
 97	                .sorted(Comparator.comparing(Claim::getId)).toList();
 98	        for (Claim claim : moved) {
 99	            claim.reassign(into.getId());
100	        }
101	        claims.saveAll(moved);
102	
103	        // Their name and aliases become the other's aliases; their patrons the other's.
104	        into.addAlias(from.getName());
105	        from.getAliases().forEach(into::addAlias);
106	        for (Long patronId : from.getPatronIds()) {
107	            if (!patronId.equals(into.getId())) {
108	                into.addPatron(patronId);
109	            }
110	        }
111	        // Anyone naming them as a patron names the other instead.
112	        for (Person other : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
113	            if (other.getId().equals(from.getId()) || !other.removePatron(from.getId())) {
114	                continue;
115	            }
116	            if (!other.getId().equals(into.getId())) {
117	                other.addPatron(into.getId());
118	            }
119	            people.save(other);
120	        }
121	
122	        // Their pool memberships move to the other, shares added where the other is already a member.
123	        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
124	            PoolMember theirs = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId()).orElse(null);
125	            if (theirs != null) {
126	                theirs.addShare(member.getShare());
127	                poolMembers.save(theirs);
128	                poolMembers.delete(member);
129	            } else {
130	                member.moveTo(into.getId());
131	                poolMembers.save(member);
132	            }
133	        }
134	
135	        // The crews they lead are the other's to lead; their crew memberships move to the other.
136	        crews.merge(from, into);
137	
138	        // Their plans become the other's.
139	        for (Plan plan : plans.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId())) {
140	            plan.moveTo(into.getId());
141	            plans.save(plan);
142	        }
143	
144	        // Their statements join the other's; their watchers are dropped, and they leave the sheet with
145	        // their holds and contact.
146	        statements.handOver(sheetId, from, into);
147	        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
148	        String fromName = from.getName();
149	        from.park(into.getId());
150	        people.saveAndFlush(from);
151	        merges.save(new PersonMerge(sheetId, from.getId(), into.getId(), user, sheets.today(sheetId),
152	                moved.stream().map(Claim::getId).toList()));
153	        Person saved = people.saveAndFlush(into);
154	        statements.reread(saved);
155	
156	        // The moved claims are listed after the other's own, in the order they were added.
157	        moved.forEach(claim -> claims.relist(claim.getId()));
158	
159	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user
160	                + " from=" + fromName + " into=" + saved.getName());
161	        rollups.audit(sheetId, user, before);
162	        return people.findByIdAndSheetId(intoId, sheetId).orElseThrow();
163	    }
164	
165	    /**
166	     * Undo the last merge into a person on the sheet: the person merged into, as the store holds them
167	     * after. Refused unless the user is a steward and made that merge on the sheet's today, and when the
168	     * person has no merge into them to undo.
169	     */
170	    @Transactional
171	    public Person undo(String sheetId, String user, long intoId) {
172	        sheets.lock(sheetId);
173	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
174	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward undoes a merge.");
175	        }
176	        Person into = people.findByIdAndSheetId(intoId, sheetId)
177	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
178	        PersonMerge merge = merges.findFirstBySheetIdAndIntoIdOrderByIdDesc(sheetId, into.getId())
179	                .filter(last -> !last.isUndone())
180	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no merge into the person to undo."));
181	        if (!merge.getMergedBy().equals(user)) {
182	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who made a merge undoes it.");
183	        }
184	        if (!java.util.Objects.equals(merge.getMergedOn(), sheets.today(sheetId))) {
185	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a merge made today can be undone.");
186	        }
187	        long fromId = merge.getPersonId();
188	        String fromName = people.findParkedName(fromId)
189	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no merge into the person to undo."));
190	        Rollups.Rollup before = rollups.take(sheetId);
191	
192	        // Their own name and aliases are no longer the other's; no one else on the sheet may go by them.
193	        List<String> theirs = new java.util.ArrayList<>(people.findParkedAliases(fromId));
194	        theirs.add(fromName);
195	        theirs.forEach(into::removeAlias);
196	        people.saveAndFlush(into);
197	        for (String name : theirs) {
198	            if (people.findBySheetIdAndName(sheetId, name).isPresent()) {
199	                throw new ResponseStatusException(HttpStatus.CONFLICT, "Someone on the sheet already goes by " + name + ".");
200	            }
201	        }
202	
203	        // They are back at the end of the list, with the claims that came from them, as they are now.
204	        people.restore(fromId, Person.keyOf(fromName), people.findMaxPositionBySheetId(sheetId) + 1);
205	        List<Claim> back = claims.findAllById(merge.getClaimIds()).stream()
206	                .filter(claim -> sheetId.equals(claim.getSheetId()) && into.getId().equals(claim.getPersonId()))
207	                .toList();
208	        for (Claim claim : back) {
209	            claim.reassign(fromId);
210	        }
211	        claims.saveAll(back);
212	        merge.undo();
213	        merges.save(merge);
214	        people.flush();
215	
216	        audit.recordOnCommit("PERSON_MERGE_UNDONE sheet=" + sheetId + " by=" + user
217	                + " name=" + fromName + " from=" + into.getName());
218	        rollups.audit(sheetId, user, before);
219	        return people.findByIdAndSheetId(intoId, sheetId).orElseThrow();
220	    }
