1	package net.officefloor.hq.app.sheet;
2	
3	import jakarta.servlet.http.HttpServletRequest;
4	import jakarta.servlet.http.HttpServletResponse;
5	import java.util.Map;
6	import org.springframework.context.annotation.Configuration;
7	import org.springframework.http.HttpMethod;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.web.server.ResponseStatusException;
10	import org.springframework.web.servlet.HandlerInterceptor;
11	import org.springframework.web.servlet.HandlerMapping;
12	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
13	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
14	
15	/**
16	 * Refuse every change anyone asks for on an archived sheet: any request other than a read, or the
17	 * loading of the sheet, is turned away before it reaches its handler, so it writes nothing and audits
18	 * nothing. A bulk move is the exception: it reaches its handler, which refuses each claim selected.
19	 */
20	@Configuration
21	public class ArchiveGuard implements WebMvcConfigurer, HandlerInterceptor {
22	
23	    private final SheetService sheets;
24	
25	    public ArchiveGuard(SheetService sheets) {
26	        this.sheets = sheets;
27	    }
28	
29	    @Override
30	    public void addInterceptors(InterceptorRegistry registry) {
31	        // A bulk move answers how many claims it refused, so it is let through and refuses each.
32	        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load",
33	                "/api/sheets/*/claims/open", "/api/sheets/*/claims/settle");
34	    }
35	
36	    @Override
37	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
38	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
39	            return true;
40	        }
41	        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
42	        if (!(variables instanceof Map<?, ?> vars)) {
43	            return true;
44	        }
45	        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
46	        if (sheetId instanceof String id && sheets.archived(id)) {
47	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it may change.");
48	        }
49	        return true;
50	    }
51	}
