 33	 * sheet when they arrive, so every forward-only rate saved there before applies to them. When someone on the other sheet already
 34	 * goes by their name or an alias, they are merged into that person there: their claims listed after
 35	 * the other's own, their name and aliases joined to the other's aliases, their statements joined to
 36	 * the other's (the other's last staying the other's, or, the other having none, becoming theirs), and
 37	 * their contact dropped.
 38	 */
 39	@Service
 40	public class TransferService {
 41	
 42	    private final PersonRepository people;
 43	    private final ClaimRepository claims;
 44	    private final StatementService statements;
 45	    private final WatchRepository watches;
 46	    private final PoolMemberRepository poolMembers;
 47	    private final CrewService crews;
 48	    private final RoleService roles;
 49	    private final SheetService sheets;
 50	    private final PeriodService periods;
 51	    private final Rollups rollups;
 52	    private final Audit audit;
 53	
 54	    public TransferService(PersonRepository people, ClaimRepository claims, StatementService statements,
 55	            WatchRepository watches, PoolMemberRepository poolMembers, CrewService crews, RoleService roles, SheetService sheets,
 56	            PeriodService periods, Rollups rollups, Audit audit) {
 57	        this.people = people;
 58	        this.claims = claims;
 59	        this.statements = statements;
 60	        this.watches = watches;
 61	        this.poolMembers = poolMembers;
 62	        this.crews = crews;
 63	        this.roles = roles;
 64	        this.sheets = sheets;
 65	        this.periods = periods;
 66	        this.rollups = rollups;
 67	        this.audit = audit;
 68	    }
 69	
 70	    /**
 71	     * Transfer a person to another sheet by its id. Refused unless the user is a steward on this sheet,
 72	     * for this sheet's own id, for an archived sheet, for a retired person, when their
 73	     * contact is already in use on the other sheet (unless they are merged there), and when the person
 74	     * they would be merged into is retired.
 75	     */
 76	    @Transactional
 77	    public void transfer(String sheetId, String user, long personId, String toSheetId) {
 78	        // Both sheets are locked, always in the same order, so two transfers between them wait in turn.
 79	        Stream.of(sheetId, toSheetId).sorted().forEach(sheets::lock);
 80	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
 81	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward transfers people.");
 82	        }
 83	        Person person = people.findByIdAndSheetId(personId, sheetId)
 84	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
 85	        if (sheetId.equals(toSheetId)) {
 86	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet.");
 87	        }
 88	        if (sheets.archived(toSheetId)) {
 89	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is archived.");
 90	        }
 91	        if (person.getRetiredFrom() != null) {
 92	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred.");
 93	        }
 94	        // Someone there going by their name or an alias takes them in, as a merge would.
 95	        Person into = Stream.concat(Stream.of(person.getName()), person.getAliases().stream())
 96	                .map(name -> people.findBySheetIdAndName(toSheetId, name)).flatMap(Optional::stream)
 97	                .findFirst().orElse(null);
 98	        if (into != null && into.getRetiredFrom() != null) {
 99	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
100	        }
101	        if (into == null && person.getContact() != null
102	                && people.findBySheetIdAndContact(toSheetId, person.getContact()).isPresent()) {
103	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the other sheet.");
104	        }
105	        Rollups.Rollup before = rollups.take(sheetId);
106	        Rollups.Rollup toBefore = rollups.take(toSheetId);
107	
108	        // Anyone naming them as a patron no longer does; their pool memberships and watchers go.
109	        for (Person other : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
110	            if (!other.getId().equals(person.getId()) && other.removePatron(person.getId())) {
111	                people.save(other);
112	            }
113	        }
114	        poolMembers.deleteAll(poolMembers.findByPersonIdOrderByIdAsc(person.getId()));
115	        // Their crew memberships go, and so do the crews they lead.
116	        crews.leave(person);
117	        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, person.getId()));
118	
119	        if (into == null) {
120	            int last = people.findMaxPositionBySheetId(toSheetId);
121	            person.transferTo(toSheetId, sheets.today(toSheetId));
122	            person.setPosition(last + 1);
123	            people.saveAndFlush(person);
124	            statements.follow(sheetId, person);
125	        }
126	
127	        // Their claims follow, each that had a number taking the other sheet's next in the order opened.
128	        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, person.getId()).stream()
129	                .sorted(Comparator.comparing((Claim claim) -> claim.openedOn(),
130	                        Comparator.nullsLast(Comparator.<LocalDate>naturalOrder())).thenComparing(Claim::getId))
131	                .toList();
132	        // The numbers are all taken before any claim moves, so none is written there under its old one.
133	        Map<String, String> numbers = new HashMap<>();
134	        for (Claim claim : moved) {
135	            if (claim.getNumber() != null) {
136	                numbers.put(claim.getNumber(), periods.nextClaimNumber(toSheetId, claim.getDueBy()));
137	            }
138	        }
139	        for (Claim claim : moved) {
140	            claim.transferTo(toSheetId);
141	            if (claim.getNumber() != null) {
142	                claim.number(numbers.get(claim.getNumber()));
143	            }
144	            claim.renumberLinks(numbers);
145	            if (into != null) {
146	                claim.reassign(into.getId());
147	            }
148	        }
149	        claims.saveAllAndFlush(moved);
150	
151	        String name = person.getName();
152	        if (into != null) {
153	            // Their name and aliases join the other's aliases, and they leave with their holds and contact.
154	            into.addAlias(name);
155	            person.getAliases().forEach(into::addAlias);
156	            statements.handOver(sheetId, person, into);
157	            people.delete(person);
158	            people.flush();
159	            people.saveAndFlush(into);
160	            // The arriving claims are listed after the other's own, in the order they were added.
161	            moved.stream().map(Claim::getId).sorted().forEach(claims::relist);
162	        }
163	        // The arriving claims are added to the other sheet now: a forward-only rate saved there applies to them.
164	        moved.stream().map(Claim::getId).sorted().forEach(claims::arrive);
165	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user + " name=" + name
166	                + " to=" + toSheetId);
167	        rollups.audit(sheetId, user, before);
168	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + user + " name=" + name
169	                + " from=" + sheetId);
170	        if (into != null) {
171	            audit.recordOnCommit("PERSON_MERGED sheet=" + toSheetId + " by=" + user + " from=" + name
172	                    + " into=" + into.getName());
173	        }
174	        rollups.audit(toSheetId, user, toBefore);
175	    }
176	
177	    /**
178	     * Undo the transfer that brought a person to this sheet: they are transferred back to the sheet they
179	     * came from by exactly the transfer's rules and records, and this sheet then records the undo. Refused
180	     * unless the user is a steward on this sheet and the person arrived here by transfer on the sheet's today.
181	     */
182	    @Transactional
183	    public void undo(String sheetId, String user, long personId) {
184	        Person person = people.findByIdAndSheetId(personId, sheetId)
185	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
186	        String fromSheetId = person.getOriginSheetId();
187	        if (fromSheetId != null) {
188	            Stream.of(sheetId, fromSheetId).sorted().forEach(sheets::lock);
189	        } else {
190	            sheets.lock(sheetId);
191	        }
192	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
193	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward undoes a transfer.");
194	        }
195	        if (!person.arrivedOn(sheets.today(sheetId))) {
196	            throw new ResponseStatusException(HttpStatus.CONFLICT,
197	                    "Only a transfer that brought the person here today can be undone.");
198	        }
199	        String name = person.getName();
200	        Rollups.Rollup before = rollups.take(sheetId);
201	        transfer(sheetId, user, personId, fromSheetId);
202	        audit.recordOnCommit("PERSON_TRANSFER_UNDONE sheet=" + sheetId + " by=" + user + " name=" + name
203	                + " to=" + fromSheetId);
204	        rollups.audit(sheetId, user, before);
205	    }
206	}
