200	    /** Copy a sheet's rows of a table to the clone, with the columns named. */
201	    private void copyRows(String table, String columns, String toSheetId, String sheetId) {
202	        jdbc.update("INSERT INTO " + table + " (sheet_id, " + columns + ") SELECT ?, " + columns + " FROM " + table
203	                + " WHERE sheet_id = ?" + (hasId(table) ? " ORDER BY id" : ""), toSheetId, sheetId);
204	    }
205	
206	    /** Copy the rows of a child table from one parent row to another, oldest first. */
207	    private void copyChildren(String table, String key, String columns, long to, long from) {
208	        jdbc.update("INSERT INTO " + table + " (" + key + ", " + columns + ") SELECT ?, " + columns + " FROM " + table
209	                + " WHERE " + key + " = ?" + (hasId(table) ? " ORDER BY id" : ""), to, from);
210	    }
211	
212	    /** Whether a table has its own id column to keep its rows' order by. */
213	    private static boolean hasId(String table) {
214	        return !List.of("sheet_setting", "sheet_permission", "person_grade", "person_terms", "person_hold", "person_alias",
215	                "person_retirement").contains(table);
216	    }
217	
218	    /** Insert one row, answering its generated id. */
219	    private long insert(String sql, Object... args) {
220	        KeyHolder keys = new GeneratedKeyHolder();
221	        jdbc.update(connection -> {
222	            PreparedStatement statement = connection.prepareStatement(sql, new String[] { "ID" });
223	            for (int i = 0; i < args.length; i++) {
224	                statement.setObject(i + 1, args[i]);
225	            }
226	            return statement;
227	        }, keys);
228	        return keys.getKey().longValue();
229	    }
230	}
