 76	/**
 77	 * Marks each change a user asks for on a sheet while a delegation to them is in force on the sheet's
 78	 * today with the steward they act for, so every audit record of the change names that steward.
 79	 */
 80	@Configuration
 81	public class DelegationGuard implements WebMvcConfigurer, HandlerInterceptor {
 82	
 83	    private final DelegationService delegations;
 84	
 85	    public DelegationGuard(DelegationService delegations) {
 86	        this.delegations = delegations;
 87	    }
 88	
 89	    @Override
 90	    public void addInterceptors(InterceptorRegistry registry) {
 91	        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load");
 92	    }
 93	
 94	    @Override
 95	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
 96	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
 97	            return true;
 98	        }
 99	        String header = request.getHeader(SignedIn.HEADER);
100	        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
101	        if (header == null || !(variables instanceof Map<?, ?> vars)) {
102	            return true;
103	        }
104	        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
105	        if (sheetId instanceof String id) {
106	            delegations.actingFor(id, SignedIn.name(header))
107	                    .ifPresent(steward -> request.setAttribute(Audit.ACTING_FOR, steward));
108	        }
109	        return true;
110	    }
