215	@Service
216	public class DelegationService {
217	
218	    private final DelegationRepository delegations;
219	    private final RoleRepository roles;
220	    private final SheetService sheets;
221	    private final Audit audit;
222	
223	    public DelegationService(DelegationRepository delegations, RoleRepository roles, SheetService sheets, Audit audit) {
224	        this.delegations = delegations;
225	        this.roles = roles;
226	        this.sheets = sheets;
227	        this.audit = audit;
228	    }
229	
230	    /** The delegations made on the sheet, in the order they were made. */
231	    @Transactional(readOnly = true)
232	    public List<Delegation> list(String sheetId) {
233	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
234	    }
235	
236	    /**
237	     * The steward a user name acts for on the sheet's today: the one who made the latest delegation to
238	     * it whose range holds the sheet's today; empty when none does.
239	     */
240	    @Transactional(readOnly = true)
241	    public Optional<String> actingFor(String sheetId, String userName) {
242	        List<Delegation> made = delegations.findBySheetIdAndUserNameOrderByIdDesc(sheetId, userName);
243	        if (made.isEmpty()) {
244	            return Optional.empty();
245	        }
246	        LocalDate today = sheets.today(sheetId);
247	        return made.stream()
248	                .filter(d -> d.covers(today)).map(Delegation::getSteward).findFirst();
249	    }
250	
251	    /**
252	     * Delegate the steward role to a user name from a date to a date, inclusive. Refused unless the
253	     * user delegating is a steward in their own right, and when the to-date is before the from-date.
254	     */
255	    @Transactional
256	    public Delegation delegate(String sheetId, String user, String userName, LocalDate from, LocalDate to) {
257	        sheets.lock(sheetId);
258	        boolean steward = roles.findBySheetIdAndUserName(sheetId, user)
259	                .map(r -> Role.STEWARD.equals(r.getRole())).orElse(false);
260	        if (!steward) {
261	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward delegates the steward role.");
262	        }
263	        if (to.isBefore(from)) {
264	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
265	        }
266	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, userName, user, from, to));
267	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + userName
268	                + " from=" + from + " to=" + to);
269	        return saved;
270	    }
271	}
