508	import org.springframework.stereotype.Service;
509	import org.springframework.transaction.annotation.Transactional;
510	
511	/** The roles user names have on a sheet: listed, set and looked up. */
512	@Service
513	public class RoleService {
514	
515	    private final RoleRepository roles;
516	    private final RoleChangeRepository changes;
517	    private final SheetService sheets;
518	    private final DelegationService delegations;
519	    private final Audit audit;
520	
521	    public RoleService(RoleRepository roles, RoleChangeRepository changes, SheetService sheets,
522	            DelegationService delegations, Audit audit) {
523	        this.roles = roles;
524	        this.changes = changes;
525	        this.sheets = sheets;
526	        this.delegations = delegations;
527	        this.audit = audit;
528	    }
529	
530	    /** The roles set on the sheet, by user name. */
531	    @Transactional(readOnly = true)
532	    public List<Role> list(String sheetId) {
533	        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
534	    }
535	
536	    /**
537	     * The roles in force on the sheet at the end of a date, by user name: for each name, the last role
538	     * set on it on a sheet-today on or before that date. A name with none set by then is not listed.
539	     */
540	    @Transactional(readOnly = true)
541	    public List<Role> listAsOf(String sheetId, LocalDate asOf) {
542	        Map<String, Role> inForce = new LinkedHashMap<>();
543	        for (RoleChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
544	            if (change.getSetOn() == null || !change.getSetOn().isAfter(asOf)) {
545	                inForce.put(change.getUserName(), new Role(sheetId, change.getUserName(), change.getRole()));
546	            }
547	        }
548	        return inForce.values().stream().sorted(Comparator.comparing(Role::getUserName)).toList();
549	    }
550	
551	    /** The role set for a user name on the sheet in force at the end of a date (see {@link #listAsOf}), else clerk. */
552	    @Transactional(readOnly = true)
553	    public String roleAsOf(String sheetId, String userName, LocalDate asOf) {
554	        return listAsOf(sheetId, asOf).stream().filter(role -> role.getUserName().equals(userName))
555	                .map(Role::getRole).findFirst().orElse(Role.CLERK);
556	    }
557	
558	    /**
559	     * The role a user name acts in on the sheet: steward while a delegation to it is in force on the
560	     * sheet's today, else the one set for it, else clerk.
561	     */
562	    @Transactional(readOnly = true)
563	    public String roleOf(String sheetId, String userName) {
564	        if (delegations.actingFor(sheetId, userName).isPresent()) {
565	            return Role.STEWARD;
566	        }
567	        return roles.findBySheetIdAndUserName(sheetId, userName).map(Role::getRole).orElse(Role.CLERK);
568	    }
569	
570	    /**
571	     * Whether a user name may take an action (open, settle, void, reassign, close, reopen or today) on the
572	     * sheet: its role is among those the sheet's permission matrix sets for it, else its standing rule.
573	     */
574	    @Transactional(readOnly = true)
575	    public boolean permits(String sheetId, String userName, String action) {
576	        return sheets.load(sheetId).permits(action, roleOf(sheetId, userName));
577	    }
578	
579	    /** Set the role of a user name on the sheet, replacing any it had. */
580	    @Transactional
581	    public Role set(String sheetId, String user, String userName, String role) {
582	        LocalDate today = sheets.lock(sheetId).getToday();
583	        Role saved = roles.findBySheetIdAndUserName(sheetId, userName)
584	                .orElseGet(() -> new Role(sheetId, userName, role));
585	        saved.setRole(role);
586	        saved = roles.saveAndFlush(saved);
587	        changes.save(new RoleChange(sheetId, saved.getUserName(), saved.getRole(), today));
588	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user
589	                + " user=" + saved.getUserName() + " role=" + saved.getRole());
590	        return saved;
591	    }
592	}
