595	import jakarta.servlet.http.HttpServletRequest;
596	import jakarta.servlet.http.HttpServletResponse;
597	import java.util.Map;
598	import net.officefloor.hq.app.SignedIn;
599	import org.springframework.context.annotation.Configuration;
600	import org.springframework.http.HttpMethod;
601	import org.springframework.http.HttpStatus;
602	import org.springframework.web.server.ResponseStatusException;
603	import org.springframework.web.servlet.HandlerInterceptor;
604	import org.springframework.web.servlet.HandlerMapping;
605	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
606	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
607	
608	/**
609	 * Refuse every change a viewer asks for on a sheet: any request other than a read, or the loading
610	 * of the sheet, is turned away before it reaches its handler, so it writes nothing and audits nothing.
611	 * A bulk open, settle or void, a bulk grade, a bulk retire, a bulk hold and a plan generate are the exceptions: each reaches its handler, which
612	 * refuses each claim or person a viewer selected, or each claim a viewer's generate would make.
613	 */
614	@Configuration
615	public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {
616	
617	    private final RoleService roles;
618	
619	    public ViewerGuard(RoleService roles) {
620	        this.roles = roles;
621	    }
622	
623	    @Override
624	    public void addInterceptors(InterceptorRegistry registry) {
625	        // A bulk move answers how many claims it refused, and a bulk grade, retire or hold how many people it changed,
626	        // and a plan generate how many claims it made, so a viewer's is let through and refuses each.
627	        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**").excludePathPatterns("/api/sheets/*/load",
628	                "/api/sheets/*/claims/open", "/api/sheets/*/claims/settle", "/api/sheets/*/claims/void",
629	                "/api/sheets/*/people/grade",
630	                "/api/sheets/*/people/retire", "/api/sheets/*/people/hold", "/api/sheets/*/plans/generate");
631	    }
632	
633	    @Override
634	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
635	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
636	            return true;
637	        }
638	        String header = request.getHeader(SignedIn.HEADER);
639	        Object variables = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
640	        if (header == null || !(variables instanceof Map<?, ?> vars)) {
641	            return true;
642	        }
643	        Object sheetId = vars.containsKey("sheetId") ? vars.get("sheetId") : vars.get("id");
644	        if (sheetId instanceof String id && Role.VIEWER.equals(roles.roleOf(id, SignedIn.name(header)))) {
645	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything on the sheet.");
646	        }
647	        return true;
648	    }
649	}
