22	/**
23	 * The sheet's figures as the screen shows them: what each person has claimed, their due-total and
24	 * overdue-total, and the sheet's claimed-total, due-total and overdue-total. A change takes them
25	 * before it writes and has them audited after its own records, so every figure it moves is recorded.
26	 */
27	@Service
28	public class Rollups {
29	
30	    /** Shown in place of a due-total when the grade has no rate. */
31	    private static final String NO_RATE = "n/a";
32	
33	    /**
34	     * A person's figures: what they have claimed, their due-total (null when n/a) and their
35	     * overdue-total (the due of their counting overdue claims), with their settled-total (the due of
36	     * their counting SETTLED claims that correct nothing) and how many of their counting claims are overdue, which make their score,
37	     * and the due of all their counting SETTLED claims and of their counting OPEN and PENDING claims as the
38	     * screen shows them.
39	     */
40	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal,
41	            BigDecimal settledTotal, int overdueCount, BigDecimal settledShown, BigDecimal openShown) {
42	
43	        /**
44	         * Their score as the screen shows it: their settled-total over 100, less 5 for each overdue
45	         * claim, rounded half to even to a whole number.
46	         */
47	        public long score() {
48	            return settledTotal.subtract(BigDecimal.valueOf(500L * overdueCount))
49	                    .divide(BigDecimal.valueOf(100), 0, RoundingMode.HALF_EVEN).longValueExact();
50	        }
51	
52	        boolean sameAs(Figures other) {
53	            return other != null && same(claimed, other.claimed) && same(dueTotal, other.dueTotal)
54	                    && same(overdueTotal, other.overdueTotal);
55	        }
56	    }
57	
58	    /**
59	     * The sheet's figures: each person's by id, in list order, the sheet's totals, and how many of its
60	     * counting claims are overdue.
61	     */
62	    public record Rollup(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
63	            BigDecimal overdueTotal, int overdueCount) {
64	    }
65	
66	    private final PersonRepository people;
67	    private final ClaimRepository claims;
68	    private final SheetRepository sheets;
69	    private final Dues dues;
70	    private final Audit audit;
71	    private final PoolCuts cuts;
72	
73	    public Rollups(PersonRepository people, ClaimRepository claims, SheetRepository sheets,
74	            Dues dues, Audit audit, PoolCuts cuts) {
75	        this.cuts = cuts;
76	        this.people = people;
77	        this.claims = claims;
78	        this.sheets = sheets;
79	        this.dues = dues;
80	        this.audit = audit;
81	    }
82	
83	    /** The sheet's figures as they stand now in the current transaction. */
84	    public Rollup take(String sheetId) {
85	        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
86	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
87	        Sheet sheet = sheets.findById(sheetId).orElse(null);
88	        return take(sheet, dues.live(sheetId), sheetPeople, claims.findBySheetIdOrderByIdDesc(sheetId),
89	                cuts.personCuts(sheet, sheetPeople.values()));
90	    }
91	
92	    /**
93	     * The sheet's figures over its records as they stand now, read as if its today were a preview day
94	     * (null: its own today), held in no store.
95	     */
96	    public Rollup take(String sheetId, LocalDate preview) {
97	        Sheet now = sheets.findById(sheetId).orElse(null);
98	        if (preview == null || now == null) {
99	            return take(sheetId);
100	        }
101	        Sheet then = now.asOf(preview, now.getDated(), now.getPolicyDate());
102	        Map<Long, Person> sheetPeople = new LinkedHashMap<>();
103	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
104	        return take(then, previewBasis(then), sheetPeople, claims.findBySheetIdOrderByIdDesc(sheetId),
105	                cuts.personCuts(then, sheetPeople.values()));
106	    }
107	
108	    /** The basis a sheet held in no store, with a preview day as its today, reads its dues against: its live one. */
109	    public Dues.Basis previewBasis(Sheet then) {
110	        Dues.Basis live = dues.live(then.getId());
111	        return new Dues.Basis(then, live.rates(), live.inherited(), live.corrected());
112	    }
113	
114	    /**
115	     * A sheet's figures read from what is given, as {@link #take(Sheet, Dues.Basis, Map, Iterable, Map)}
116	     * with no one's cuts.
117	     */
118	    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims) {
119	        return take(sheet, basis, sheetPeople, sheetClaims, Map.of());
120	    }
121	
122	    /**
123	     * A sheet's figures read from what is given, held in no store or not: the sheet (null when not found;
124	     * its today is the day they are read on), the basis their dues are read against, its people by id in
125	     * list order, its claims, and each person's cut total by id (none: no cut), which the cap covers too.
126	     */
127	    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims,
128	            Map<Long, BigDecimal> personCuts) {
129	        LocalDate today = sheet == null ? null : sheet.getToday();
130	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
131	        for (Claim claim : sheetClaims) {
132	            if (claim.getStatus().counts()) {
133	                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
134	            }
135	        }
136	        // The parts of shared claims their holders' due-totals count, by holder, from the claims that
137	        // count for their own person; each claim's figure as read here.
138	        // A holder whose grade has no rate has a part of 0.00, which gives them no figure.
139	        Map<Claim, BigDecimal> shared = new java.util.IdentityHashMap<>();
140	        Map<Long, BigDecimal> received = new LinkedHashMap<>();
141	        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
142	            Person person = entry.getValue();
143	            for (Claim claim : byPerson.getOrDefault(entry.getKey(), List.of())) {
144	                if (claim.getShares().isEmpty()
145	                        || !person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)) {
146	                    continue;
147	                }
148	                BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()), basis);
149	                if (figure == null) {
150	                    continue;
151	                }
152	                shared.put(claim, claim.sharedParts(share -> {
153	                    Person holder = sheetPeople.get(share.getPersonId());
154	                    BigDecimal part = dues.part(claim, share,
155	                            holder == null ? null : holder.gradeOn(claim.getDate()), figure, basis);
156	                    if (part != null) {
157	                        received.merge(share.getPersonId(), part, BigDecimal::add);
158	                    }
159	                    return part;
160	                }));
161	            }
162	        }
163	        Map<Long, Figures> figures = new LinkedHashMap<>();
164	        BigDecimal claimedTotal = zero();
165	        List<BigDecimal> dueFigures = new ArrayList<>();
166	        List<BigDecimal> overdueFigures = new ArrayList<>();
167	        int overdueCount = 0;
168	        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
169	            Person person = entry.getValue();
170	            List<Claim> personClaims = byPerson.getOrDefault(entry.getKey(), List.of());
171	            BigDecimal claimed = zero();
172	            for (Claim claim : personClaims) {
173	                // What is claimed leaves out claims that correct another.
174	                if (person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)
175	                        && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
176	                    claimed = claimed.add(claim.getAmount());
177	                }
178	            }
179	            List<Claim> counting = personClaims.stream()
180	                    .filter(claim -> person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today))
181	                    .toList();
182	            BigDecimal due = zero();
183	            BigDecimal overdue = zero();
184	            BigDecimal settled = zero();
185	            BigDecimal settledShown = zero();
186	            BigDecimal openShown = zero();
187	            int personOverdue = 0;
188	            boolean figured = false;
189	            for (Claim claim : counting) {
190	                String grade = person.gradeOn(claim.getDate());
191	                boolean late = overdue(claim, sheet, grade);
192	                if (late) {
193	                    overdueCount++;
194	                    personOverdue++;
195	                }
196	                BigDecimal figure = dues.due(claim, grade, basis);
197	                if (figure != null) {
198	                    // A shared claim's own person counts its figure less its holders' parts.
199	                    due = due.add(shared.containsKey(claim) ? figure.subtract(shared.get(claim)) : figure);
200	                    figured = true;
201	                    if (late) {
202	                        overdue = overdue.add(figure);
203	                    }
204	                    if (claim.getStatus() == ClaimStatus.SETTLED) {
205	                        settledShown = settledShown.add(figure);
206	                    } else if (claim.getStatus().isOpen()) {
207	                        openShown = openShown.add(figure);
208	                    }
209	                    // The score's settled figures leave out claims that correct another.
210	                    if (claim.getStatus() == ClaimStatus.SETTLED
211	                            && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
212	                        settled = settled.add(figure);
213	                    }
214	                }
215	            }
216	            BigDecimal part = received.get(entry.getKey());
217	            if (part != null) {
218	                due = due.add(part);
219	                figured = true;
220	            }
221	            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
222	            // figure (a fixed one, or one at the grade in force on its own date).
223	            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
224	            if (!rated && !figured) {
225	                due = null;
226	            }
227	            // A due-total is at most their cap (the one in force on their latest counting claim's date)
228	            // less their cut total, not below 0.00.
229	            if (sheet != null) {
230	                due = sheet.capped(due, personCuts.getOrDefault(entry.getKey(), zero()),
231	                        counting.stream().map(Claim::getDate).toList());
232	            }
233	            figures.put(entry.getKey(), new Figures(person.getName(), claimed, due, overdue, settled, personOverdue,
234	                    settledShown, openShown));
235	            claimedTotal = claimedTotal.add(claimed);
236	            if (due != null) {
237	                dueFigures.add(due);
238	            }
239	            overdueFigures.add(overdue);
240	        }
241	        return new Rollup(figures, claimedTotal, trimmed(dueFigures), trimmed(overdueFigures), overdueCount);
242	    }
243	
244	    /**
245	     * The sum of the people's figures, leaving out the single highest and the single lowest when there
246	     * are three or more.
247	     */
248	    static BigDecimal trimmed(List<BigDecimal> figures) {
249	        BigDecimal total = zero();
250	        for (BigDecimal figure : figures) {
251	            total = total.add(figure);
252	        }
253	        if (figures.size() >= 3) {
254	            BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
255	            BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
256	            total = total.subtract(highest).subtract(lowest);
257	        }
258	        return total;
259	    }
260	
261	    /**
262	     * Record, once the change commits, one ROLLUP line per person whose figures moved since
263	     * {@code before} (a person new since then counts as moved), then a TOTALS line when any of the sheet's
264	     * totals moved, then one ALERT line per person, in list order, whose due-total went from at or below
265	     * the sheet's alert threshold (or none) to above it.
266	     */
267	    public void audit(String sheetId, String user, Rollup before) {
268	        Rollup after = take(sheetId);
269	        after.people().forEach((id, figures) -> {
270	            if (!figures.sameAs(before.people().get(id))) {
271	                audit.recordFiguresOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
272	                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal())
273	                        + " overdue-total=" + figures.overdueTotal().toPlainString());
274	            }
275	        });
276	        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())
277	                || !same(after.overdueTotal(), before.overdueTotal())) {
278	            audit.recordFiguresOnCommit("TOTALS sheet=" + sheetId + " by=" + user
279	                    + " claimed-total=" + after.claimedTotal().toPlainString()
280	                    + " due-total=" + after.dueTotal().toPlainString()
281	                    + " overdue-total=" + after.overdueTotal().toPlainString());
282	        }
283	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
284	        if (threshold != null) {
285	            after.people().forEach((id, figures) -> {
286	                Figures was = before.people().get(id);
287	                if (above(figures.dueTotal(), threshold) && !(was != null && above(was.dueTotal(), threshold))) {
288	                    audit.recordFiguresOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
289	                            + " due-total=" + figures.dueTotal().toPlainString());
290	                }
291	            });
292	        }
293	    }
294	
295	    /** Whether a due-total is above a threshold; n/a never is. */
296	    private static boolean above(BigDecimal due, BigDecimal threshold) {
297	        return due != null && due.compareTo(threshold) > 0;
298	    }
299	
300	    /**
301	     * Whether a claim is overdue: OPEN or PENDING with its due-by (plus its grade's grace, see
302	     * {@link Sheet#lateFrom}) before the sheet's today, and not deferred on it.
303	     */
304	    private static boolean overdue(Claim claim, Sheet sheet, String grade) {
305	        if (sheet == null) {
306	            return false;
307	        }
308	        LocalDate today = sheet.getToday();
309	        return claim.getStatus().isOpen() && sheet.lateFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today)
310	                && !claim.isDeferredOn(today);
311	    }
312	
313	    /** Whether two figures are the same amount, or both n/a. */
314	    private static boolean same(BigDecimal a, BigDecimal b) {
315	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
316	    }
317	
318	    /** A due-total as shown: two decimals, or n/a. */
319	    public static String shown(BigDecimal due) {
320	        return due != null ? due.toPlainString() : NO_RATE;
321	    }
322	
323	    private static BigDecimal zero() {
324	        return BigDecimal.ZERO.setScale(2);
325	    }
326	}
