248	
249	/**
250	 * The crews on a sheet: listed with their lead and members, added, and given members. Each crew is also a
251	 * pool under its name, added with it and gone with it.
252	 */
253	@Service
254	public class CrewService {
255	
256	    /** A crew with its lead's name and its members in the order they were added. */
257	    public record CrewWithMembers(Crew crew, String lead, List<Member> members) {
258	    }
259	
260	    /** A member with the person's name. */
261	    public record Member(CrewMember member, String name) {
262	    }
263	
264	    private final CrewRepository crews;
265	    private final CrewMemberRepository members;
266	    private final PersonRepository people;
267	    private final PoolRepository pools;
268	    private final PoolMemberRepository poolMembers;
269	    private final SheetService sheets;
270	    private final Audit audit;
271	    private final Rollups rollups;
272	
273	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
274	            PoolRepository pools, PoolMemberRepository poolMembers, SheetService sheets, Audit audit,
275	            Rollups rollups) {
276	        this.rollups = rollups;
277	        this.crews = crews;
278	        this.members = members;
279	        this.people = people;
280	        this.pools = pools;
281	        this.poolMembers = poolMembers;
282	        this.sheets = sheets;
283	        this.audit = audit;
284	    }
285	
286	    /** The sheet's crews in the order they were added, with their lead and members. */
287	    @Transactional(readOnly = true)
288	    public List<CrewWithMembers> list(String sheetId) {
289	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
290	        Map<Long, String> names = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
291	                .collect(Collectors.toMap(Person::getId, Person::getName));
292	        Map<Long, List<Member>> byCrew = members.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList())
293	                .stream().map(m -> new Member(m, names.get(m.getPersonId())))
294	                .collect(Collectors.groupingBy(m -> m.member().getCrewId()));
295	        return all.stream().map(c -> new CrewWithMembers(c, names.get(c.getLeadId()),
296	                byCrew.getOrDefault(c.getId(), List.of()))).toList();
297	    }
298	
299	    /**
300	     * Add a crew led by a person on the sheet, and its pool under its name; refused when its name, trimmed, is
301	     * blank or already a crew's or a pool's on the sheet.
302	     */
303	    @Transactional
304	    public CrewWithMembers add(String sheetId, String user, String name, long leadId) {
305	        String trimmed = name.strip();
306	        if (trimmed.isEmpty()) {
307	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A crew needs a name.");
308	        }
309	        sheets.lock(sheetId);
310	        Person lead = people.findByIdAndSheetId(leadId, sheetId)
311	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
312	        if (crews.existsBySheetIdAndName(sheetId, trimmed)) {
313	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is already a crew by that name.");
314	        }
315	        if (pools.existsBySheetIdAndName(sheetId, trimmed)) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is already a pool by that name.");
317	        }
318	        Rollups.Rollup before = rollups.take(sheetId);
319	        Crew saved = crews.saveAndFlush(new Crew(sheetId, trimmed, lead.getId()));
320	        pools.saveAndFlush(Pool.ofCrew(sheetId, trimmed, saved.getId()));
321	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + trimmed
322	                + " lead=" + lead.getName());
323	        rollups.audit(sheetId, user, before);
324	        return new CrewWithMembers(saved, lead.getName(), List.of());
325	    }
326	
327	    /** Add a person on the sheet to a crew; refused when they lead it or are already in it. */
328	    @Transactional
329	    public CrewWithMembers addMember(String sheetId, String user, long crewId, long personId) {
330	        sheets.lock(sheetId);
331	        Crew crew = crews.findBySheetIdAndId(sheetId, crewId)
332	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew."));
333	        Person person = people.findByIdAndSheetId(personId, sheetId)
334	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
335	        if (crew.getLeadId().equals(personId)) {
336	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The lead is not a member of their own crew.");
337	        }
338	        if (members.existsByCrewIdAndPersonId(crewId, personId)) {
339	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already in the crew.");
340	        }
341	        Rollups.Rollup before = rollups.take(sheetId);
342	        members.saveAndFlush(new CrewMember(crewId, personId));
343	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
344	                + " name=" + person.getName());
345	        rollups.audit(sheetId, user, before);
346	        return list(sheetId).stream().filter(c -> c.crew().getId().equals(crewId)).findFirst().orElseThrow();
347	    }
348	
349	    /**
350	     * A person merged into another: the crews they lead are led by the other, and their memberships move to
351	     * the other, dropped where the other is already in the crew or leads it.
352	     */
353	    @Transactional
354	    public void merge(Person from, Person into) {
355	        for (Crew crew : crews.findByLeadIdOrderByIdAsc(from.getId())) {
356	            crew.leadBy(into.getId());
357	            crews.save(crew);
358	            members.findByCrewIdInOrderByIdAsc(List.of(crew.getId())).stream()
359	                    .filter(m -> m.getPersonId().equals(into.getId())).forEach(members::delete);
360	        }
361	        crews.flush();
362	        for (CrewMember member : members.findByPersonIdOrderByIdAsc(from.getId())) {
363	            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
364	            if (crew.getLeadId().equals(into.getId())
365	                    || members.existsByCrewIdAndPersonId(member.getCrewId(), into.getId())) {
366	                members.delete(member);
367	            } else {
368	                member.moveTo(into.getId());
369	                members.save(member);
370	            }
371	            members.flush();
372	        }
373	    }
374	
375	    /**
376	     * A person leaving the sheet: their memberships go, and so do the crews they lead with their members and
377	     * their pools, each with its place in another pool.
378	     */
379	    @Transactional
380	    public void leave(Person person) {
381	        members.deleteAll(members.findByPersonIdOrderByIdAsc(person.getId()));
382	        List<Crew> led = crews.findByLeadIdOrderByIdAsc(person.getId());
383	        List<Pool> ledPools = pools.findByCrewIdInOrderByIdAsc(led.stream().map(Crew::getId).toList());
384	        ledPools.forEach(p -> poolMembers.deleteAll(poolMembers.findByMemberPoolId(p.getId())));
385	        poolMembers.flush();
386	        pools.deleteAll(ledPools);
387	        pools.flush();
388	        members.deleteAll(members.findByCrewIdInOrderByIdAsc(led.stream().map(Crew::getId).toList()));
389	        crews.deleteAll(led);
390	        members.flush();
391	        crews.flush();
392	    }
393	}

