27	/**
28	 * The figures of a sheet consolidated over it and all its descendants (the sheets naming it as their
29	 * parent, theirs, and so on), each sheet's as that sheet shows them now, or as it stood at the end of an
30	 * as-of date.
31	 */
32	@Service
33	public class Consolidation {
34	
35	    /**
36	     * The number of people (those whose names or aliases match counted once), the people's due-totals and
37	     * overdue-totals over the whole tree added up, leaving out the single highest and single lowest when
38	     * there are three or more, per grade the due-totals of the
39	     * people not retired who have it in force on their sheet's today (those shown as n/a skipped) added
40	     * up, per status how many claims have it, and the people's settled-totals, open-totals and cut totals
41	     * over the whole tree added up, trimmed once as the due-totals are.
42	     */
43	    public record Consolidated(int peopleCount, BigDecimal dueTotal, BigDecimal overdueTotal,
44	            Map<String, BigDecimal> gradeDueTotals, Map<String, Integer> statusCounts, BigDecimal settledTotal,
45	            BigDecimal openTotal, BigDecimal cutTotal) {
46	    }
47	
48	    /** A sheet's figures with the people and claims they were read from, and each person's cut total by id. */
49	    private record Taken(Sheet sheet, Rollups.Rollup rollup, Map<Long, Person> people, Iterable<Claim> claims,
50	            Map<Long, BigDecimal> cuts) {
51	    }
52	
53	    private final SheetRepository sheets;
54	    private final Rollups rollups;
55	    private final SheetHistory history;
56	    private final Dues dues;
57	    private final PersonRepository people;
58	    private final ClaimRepository claims;
59	    private final PoolCuts cuts;
60	
61	    public Consolidation(SheetRepository sheets, Rollups rollups, SheetHistory history, Dues dues,
62	            PersonRepository people, ClaimRepository claims, PoolCuts cuts) {
63	        this.cuts = cuts;
64	        this.sheets = sheets;
65	        this.rollups = rollups;
66	        this.history = history;
67	        this.dues = dues;
68	        this.people = people;
69	        this.claims = claims;
70	    }
71	
72	    /** The sheet's figures added to those of all its descendants, each as it stands now. */
73	    @Transactional(readOnly = true)
74	    public Consolidated of(String sheetId) {
75	        return of(sheetId, null);
76	    }
77	
78	    /**
79	     * The sheet's figures added to those of all its descendants (the tree as it is set now), each sheet's
80	     * as it stood at the end of an as-of date (null: as it stands now), with that date as its today.
81	     */
82	    @Transactional(readOnly = true)
83	    public Consolidated of(String sheetId, LocalDate asOf) {
84	        return of(sheetId, asOf, null);
85	    }
86	
87	    /**
88	     * As {@link #of(String, LocalDate)}; with no as-of date but a preview day, each sheet's figures over its
89	     * records as they stand now, read as if its today were that day.
90	     */
91	    @Transactional(readOnly = true)
92	    public Consolidated of(String sheetId, LocalDate asOf, LocalDate preview) {
93	        List<String> all = new ArrayList<>();
94	        all.add(sheetId);
95	        all.addAll(sheets.descendants(sheetId));
96	        List<BigDecimal> dueFigures = new ArrayList<>();
97	        List<BigDecimal> overdueFigures = new ArrayList<>();
98	        List<BigDecimal> settledFigures = new ArrayList<>();
99	        List<BigDecimal> openFigures = new ArrayList<>();
100	        List<BigDecimal> cutFigures = new ArrayList<>();
101	        List<Set<String>> persons = new ArrayList<>();
102	        Map<String, BigDecimal> grades = new TreeMap<>();
103	        Map<String, Integer> statuses = new TreeMap<>();
104	        for (String id : all) {
105	            Taken taken = asOf != null ? asOf(id, asOf) : preview != null ? preview(id, preview) : now(id);
106	            Rollups.Rollup rollup = taken.rollup();
107	            rollup.people().forEach((personId, figures) -> {
108	                if (figures.dueTotal() != null) {
109	                    dueFigures.add(figures.dueTotal());
110	                }
111	                overdueFigures.add(figures.overdueTotal());
112	                settledFigures.add(figures.settledShown());
113	                openFigures.add(figures.openShown());
114	                cutFigures.add(taken.cuts().getOrDefault(personId, BigDecimal.ZERO.setScale(2)));
115	            });
116	            rollup.people().keySet().forEach(personId -> {
117	                Person person = taken.people().get(personId);
118	                if (person != null) {
119	                    persons.add(keys(person));
120	                }
121	            });
122	            addGradeDueTotals(taken, grades);
123	            for (Claim claim : taken.claims()) {
124	                statuses.merge(claim.getStatus().name(), 1, Integer::sum);
125	            }
126	        }
127	        return new Consolidated(distinct(persons), Rollups.trimmed(dueFigures), Rollups.trimmed(overdueFigures),
128	                grades, statuses, Rollups.trimmed(settledFigures), Rollups.trimmed(openFigures),
129	                Rollups.trimmed(cutFigures));
130	    }
131	
132	    /**
133	     * The sheet's own summary due-total per grade, as it stands now: the due-totals of the people not
134	     * retired who have it in force on its today (those shown as n/a skipped) added up; a grade nobody has
135	     * is left out. Empty when no sheet has the id.
136	     */
137	    @Transactional(readOnly = true)
138	    public Optional<Map<String, BigDecimal>> gradeDueTotals(String sheetId) {
139	        if (sheets.findById(sheetId).isEmpty()) {
140	            return Optional.empty();
141	        }
142	        Map<String, BigDecimal> grades = new TreeMap<>();
143	        addGradeDueTotals(now(sheetId), grades);
144	        return Optional.of(grades);
145	    }
