147	    /** Add a sheet's people's due-totals to the per-grade totals (see {@link Consolidated}). */
148	    private static void addGradeDueTotals(Taken taken, Map<String, BigDecimal> grades) {
149	        LocalDate today = taken.sheet() == null ? null : taken.sheet().getToday();
150	        taken.people().forEach((personId, person) -> {
151	            Rollups.Figures figures = taken.rollup().people().get(personId);
152	            if (person.getRetiredFrom() != null || today == null || figures == null) {
153	                return;
154	            }
155	            BigDecimal figure = figures.dueTotal() == null ? BigDecimal.ZERO.setScale(2) : figures.dueTotal();
156	            grades.merge(person.gradeOn(today), figure, BigDecimal::add);
157	        });
158	    }
159	
160	    /** A person's name and aliases, each as names are compared. */
161	    private static Set<String> keys(Person person) {
162	        Set<String> keys = new HashSet<>();
163	        keys.add(Person.keyOf(person.getName()));
164	        person.getAliases().forEach(alias -> keys.add(Person.keyOf(alias)));
165	        return keys;
166	    }
