168	    /**
169	     * How many people there are when those whose names or aliases match, as names are compared, are one
170	     * person (and so on through whoever they match in turn).
171	     */
172	    private static int distinct(List<Set<String>> persons) {
173	        List<Set<String>> groups = new ArrayList<>();
174	        for (Set<String> person : persons) {
175	            Set<String> merged = new HashSet<>(person);
176	            for (Iterator<Set<String>> it = groups.iterator(); it.hasNext();) {
177	                Set<String> group = it.next();
178	                if (!Collections.disjoint(group, merged)) {
179	                    merged.addAll(group);
180	                    it.remove();
181	                }
182	            }
183	            groups.add(merged);
184	        }
185	        return groups.size();
186	    }
187	
188	    /** A sheet's figures as it stands now. */
189	    private Taken now(String sheetId) {
190	        Sheet sheet = sheets.findById(sheetId).orElse(null);
191	        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
192	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
193	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
194	        Map<Long, BigDecimal> personCuts = cuts.personCuts(sheet, sheetPeople.values());
195	        return new Taken(sheet, rollups.take(sheet, dues.live(sheetId), sheetPeople, sheetClaims, personCuts),
196	                sheetPeople, sheetClaims, personCuts);
197	    }
198	
199	    /** A sheet's figures over its records as they stand now, read as if its today were a preview day. */
200	    private Taken preview(String sheetId, LocalDate day) {
201	        Sheet now = sheets.findById(sheetId).orElse(null);
202	        if (now == null) {
203	            return now(sheetId);
204	        }
205	        Sheet then = now.asOf(day, now.getDated(), now.getPolicyDate());
206	        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
207	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
208	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
209	        Map<Long, BigDecimal> personCuts = cuts.personCuts(then, sheetPeople.values());
210	        return new Taken(then, rollups.take(then, rollups.previewBasis(then), sheetPeople, sheetClaims, personCuts),
211	                sheetPeople, sheetClaims, personCuts);
212	    }
213	
214	    /**
215	     * A sheet's figures as it stood at the end of a date, with that date as its today: before its today,
216	     * as kept for that date (none when nothing was kept by then); else as it stands.
217	     */
218	    private Taken asOf(String sheetId, LocalDate day) {
219	        Sheet now = sheets.findById(sheetId).orElse(null);
220	        if (now == null) {
221	            return now(sheetId);
222	        }
223	        if (day.isBefore(now.getToday())) {
224	            return history.at(sheetId, day)
225	                    .map(then -> new Taken(then.sheet(),
226	                            rollups.take(then.sheet(), then.basis(), then.people(), then.claims().values()),
227	                            then.people(), then.claims().values(),
228	                            cuts.personCuts(then.sheet(), then.people().values())))
229	                    .orElseGet(() -> {
230	                        Sheet empty = now.asOf(day, List.of(), null, List.of());
231	                        return new Taken(empty, rollups.take(empty, dues.live(sheetId), new LinkedHashMap<>(),
232	                                List.of()), Map.of(), List.of(), Map.of());
233	                    });
234	        }
235	        Sheet then = now.asOf(day, now.getDated(), now.getPolicyDate());
236	        Dues.Basis live = dues.live(sheetId);
237	        Dues.Basis basis = new Dues.Basis(then, live.rates(), history.inherited(sheetId, day), live.corrected());
238	        LinkedHashMap<Long, Person> sheetPeople = new LinkedHashMap<>();
239	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(person -> sheetPeople.put(person.getId(), person));
240	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
241	        return new Taken(then, rollups.take(then, basis, sheetPeople, sheetClaims), sheetPeople, sheetClaims,
242	                cuts.personCuts(then, sheetPeople.values()));
243	    }
244	}
