155	import java.time.LocalDate;
156	import net.officefloor.hq.app.Audit;
157	import net.officefloor.hq.app.person.Person;
158	import net.officefloor.hq.app.person.PersonRepository;
159	import net.officefloor.hq.app.person.PersonService;
160	import net.officefloor.hq.app.role.Role;
161	import net.officefloor.hq.app.role.RoleService;
162	import net.officefloor.hq.app.rollup.Rollups;
163	import net.officefloor.hq.app.sheet.SheetService;
164	import org.springframework.http.HttpStatus;
165	import org.springframework.stereotype.Service;
166	import org.springframework.transaction.annotation.Transactional;
167	import org.springframework.web.server.ResponseStatusException;
168	
169	/**
170	 * Merging a grade into another: every person whose grade in force on the sheet's today is the merged
171	 * grade is given the other from the sheet's today, each edited as the person form would, in list order,
172	 * and then every grade record of theirs on the merged grade, whatever its date, becomes the other; then
173	 * the figures the whole merge moved. A steward only; refused for the same grade twice. Should any edit be refused, nothing is merged.
174	 */
175	@Service
176	public class GradeMergeService {
177	
178	    private final PersonService service;
179	    private final PersonRepository people;
180	    private final RoleService roles;
181	    private final SheetService sheets;
182	    private final Rollups rollups;
183	    private final Audit audit;
184	    private final GradeService grades;
185	
186	    public GradeMergeService(PersonService service, PersonRepository people, RoleService roles, SheetService sheets,
187	            Rollups rollups, Audit audit, GradeService grades) {
188	        this.grades = grades;
189	        this.service = service;
190	        this.people = people;
191	        this.roles = roles;
192	        this.sheets = sheets;
193	        this.rollups = rollups;
194	        this.audit = audit;
195	    }
196	
197	    /** Merge the grade from into the grade into: the number of people given it. */
198	    @Transactional
199	    public int merge(String sheetId, String user, String from, String into) {
200	        if (!grades.isGrade(sheetId, from) || !grades.isGrade(sheetId, into)) {
201	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "There is no such grade.");
202	        }
203	        if (from.equals(into)) {
204	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A grade cannot be merged into itself.");
205	        }
206	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
207	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward merges grades.");
208	        }
209	        sheets.lock(sheetId);
210	        Rollups.Rollup before = rollups.take(sheetId);
211	        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + user + " from=" + from + " into=" + into);
212	        LocalDate today = sheets.today(sheetId);
213	        int merged = 0;
214	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
215	            if (!from.equals(person.gradeOn(today))) {
216	                continue;
217	            }
218	            service.edit(sheetId, user, person.getId(), person.getVersion(), person.getName(), into, null,
219	                    person.getTerms(), person.getContact(), false, false);
220	            // Retroactive: every grade record of theirs on the merged grade becomes the other.
221	            people.findById(person.getId()).ifPresent(moved -> {
222	                moved.regrade(from, into);
223	                people.saveAndFlush(moved);
224	            });
225	            merged++;
226	        }
227	        rollups.audit(sheetId, user, before);
228	        return merged;
229	    }
230	}
