233	import java.util.ArrayList;
234	import java.util.List;
235	import java.util.Set;
236	import java.util.stream.Collectors;
237	import net.officefloor.hq.app.Audit;
238	import net.officefloor.hq.app.sheet.SheetService;
239	import org.springframework.http.HttpStatus;
240	import org.springframework.stereotype.Service;
241	import org.springframework.transaction.annotation.Transactional;
242	import org.springframework.web.server.ResponseStatusException;
243	
244	/**
245	 * The grades of a sheet, A, B and C and then those added to it in the order they were added, each of
246	 * which can be retired: people on a retired grade keep it, but it cannot be given to anyone else. An
247	 * added grade is a code of one to three capital letters not yet a grade of the sheet.
248	 */
249	@Service
250	public class GradeService {
251	
252	    /** The grades every sheet has. */
253	    public static final List<String> GRADES = List.of("A", "B", "C");
254	
255	    /** What any grade is: one to three capital letters. */
256	    public static final String CODE = "[A-Z]{1,3}";
257	
258	    private final RetiredGradeRepository retired;
259	    private final AddedGradeRepository added;
260	    private final SheetService sheets;
261	    private final Audit audit;
262	
263	    public GradeService(RetiredGradeRepository retired, AddedGradeRepository added, SheetService sheets, Audit audit) {
264	        this.retired = retired;
265	        this.added = added;
266	        this.sheets = sheets;
267	        this.audit = audit;
268	    }
269	
270	    /** The sheet's grades: A, B and C, then those added to it in the order they were added. */
271	    @Transactional(readOnly = true)
272	    public List<String> grades(String sheetId) {
273	        List<String> grades = new ArrayList<>(GRADES);
274	        added.findBySheetIdOrderByIdAsc(sheetId).forEach((g) -> grades.add(g.getGrade()));
275	        return grades;
276	    }
277	
278	    /** Whether the grade is one of the sheet's. */
279	    @Transactional(readOnly = true)
280	    public boolean isGrade(String sheetId, String grade) {
281	        return grade != null && (GRADES.contains(grade) || added.existsBySheetIdAndGrade(sheetId, grade));
282	    }
283	
284	    /** Refused unless the grade is one of the sheet's. */
285	    public void requireGrade(String sheetId, String grade) {
286	        if (!isGrade(sheetId, grade)) {
287	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "There is no such grade.");
288	        }
289	    }
290	
291	    /**
292	     * Add a grade to the sheet, its code trimmed: refused unless it is one to three capital letters
293	     * and not yet a grade of the sheet.
294	     */
295	    @Transactional
296	    public String add(String sheetId, String user, String code) {
297	        String grade = code == null ? "" : code.trim();
298	        if (!grade.matches(CODE)) {
299	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A grade is one to three capital letters.");
300	        }
301	        sheets.lock(sheetId);
302	        if (isGrade(sheetId, grade)) {
303	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That grade is already a grade.");
304	        }
305	        added.saveAndFlush(new AddedGrade(sheetId, grade, user));
306	        audit.recordOnCommit("GRADE_ADDED sheet=" + sheetId + " by=" + user + " grade=" + grade);
307	        return grade;
308	    }
309	
310	    /** The grades retired on the sheet. */
311	    @Transactional(readOnly = true)
312	    public Set<String> retired(String sheetId) {
313	        return retired.findBySheetId(sheetId).stream().map(RetiredGrade::getGrade).collect(Collectors.toSet());
314	    }
315	
316	    /** Retire a grade on the sheet; refused for a grade that is not one or is already retired. */
317	    @Transactional
318	    public void retire(String sheetId, String user, String grade) {
319	        requireGrade(sheetId, grade);
320	        sheets.lock(sheetId);
321	        if (retired.existsBySheetIdAndGrade(sheetId, grade)) {
322	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That grade is already retired.");
323	        }
324	        retired.saveAndFlush(new RetiredGrade(sheetId, grade, user));
325	        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
326	    }
327	}
