146	/** The holidays on a sheet: listed, added, and the days a due-by does not count as business days. */
147	@Service
148	public class HolidayService {
149	
150	    private final HolidayRepository holidays;
151	    private final SheetService sheets;
152	    private final ClaimRepository claims;
153	    private final Rollups rollups;
154	    private final Audit audit;
155	
156	    public HolidayService(HolidayRepository holidays, SheetService sheets, ClaimRepository claims, Rollups rollups,
157	            Audit audit) {
158	        this.holidays = holidays;
159	        this.sheets = sheets;
160	        this.claims = claims;
161	        this.rollups = rollups;
162	        this.audit = audit;
163	    }
164	
165	    /** The sheet's holidays by date. */
166	    @Transactional(readOnly = true)
167	    public List<Holiday> list(String sheetId) {
168	        return holidays.findBySheetIdOrderByDateAsc(sheetId);
169	    }
170	
171	    /**
172	     * Add a holiday to the sheet; refused when the date is already on its list. Every claim on the sheet
173	     * that is not SETTLED or VOID, whose due-by was not set directly, and is due by the holiday or later has its due-by worked out again from
174	     * its date, with the terms it was fixed with, against the holidays now; the figures that moves are audited.
175	     */
176	    @Transactional
177	    public Holiday add(String sheetId, String user, LocalDate date) {
178	        // Take the sheet's lock first, so the same date added twice at once cannot both pass the check.
179	        sheets.lock(sheetId);
180	        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
181	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday on this sheet.");
182	        }
183	        Rollups.Rollup before = rollups.take(sheetId);
184	        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
185	        Set<LocalDate> days = days(sheetId);
186	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
187	            ClaimStatus status = claim.getStatus();
188	            if (status != ClaimStatus.SETTLED && status != ClaimStatus.VOID && !claim.isDueBySet()
189	                    && !claim.getDueBy().isBefore(date)) {
190	                claim.workOutDueBy(days);
191	            }
192	        }
193	        claims.flush();
194	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + date);
195	        rollups.audit(sheetId, user, before);
196	        return saved;
197	    }
198	
199	    /** The terms-th business day after a date, skipping the holidays on the sheet now (see {@link BusinessDays#dueBy}). */
200	    @Transactional(readOnly = true)
201	    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
202	        return BusinessDays.dueBy(date, terms, days(sheetId));
203	    }
204	
205	    private Set<LocalDate> days(String sheetId) {
206	        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
207	                .collect(Collectors.toSet());
208	    }
209	}
