225	import org.springframework.beans.factory.annotation.Value;
226	import org.springframework.stereotype.Service;
227	import org.springframework.transaction.support.TransactionSynchronization;
228	import org.springframework.transaction.support.TransactionSynchronizationManager;
229	import org.springframework.web.context.request.RequestAttributes;
230	import org.springframework.web.context.request.RequestContextHolder;
231	
232	/**
233	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
234	 * so tests can assert side-effects by reading that file — the second test-assertion channel
235	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
236	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
237	 *
238	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
239	 * SYNC) so a test reads the record immediately.
240	 */
241	@Service
242	public class Audit {
243	
244	    /**
245	     * The request attribute naming the steward the signed-in user acts for, under a delegation in
246	     * force on the sheet's today: each record of the change then ends with for=&lt;steward&gt;.
247	     */
248	    public static final String ACTING_FOR = Audit.class.getName() + ".actingFor";
249	
250	    private final Path file;
251	
252	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
253	        this.file = Path.of(path);
254	    }
255	
256	    /** Append one audit record. Tests assert the exact line(s) in the file. */
257	    public synchronized void record(String entry) {
258	        try {
259	            Path parent = file.toAbsolutePath().getParent();
260	            if (parent != null) {
261	                Files.createDirectories(parent);
262	            }
263	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
264	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
265	        } catch (IOException e) {
266	            throw new UncheckedIOException(e);
267	        }
268	    }
269	
270	    /**
271	     * Append one audit record once the current transaction commits, so a change that is refused or
272	     * rolled back writes nothing. Records outside a transaction are appended at once.
273	     */
274	    public void recordOnCommit(String entry) {
275	        recordAfterCommit(entry + actingFor());
276	    }
277	
278	    /**
279	     * Append a record of the figures a change moved (ROLLUP and TOTALS) once the current transaction
280	     * commits; unlike the change's own records it never names a steward acted for.
281	     */
282	    public void recordFiguresOnCommit(String entry) {
283	        recordAfterCommit(entry);
284	    }
285	
286	    /** " for=<steward>" when the signed-in user acts for a steward in this request, else empty. */
287	    private static String actingFor() {
288	        RequestAttributes request = RequestContextHolder.getRequestAttributes();
289	        Object steward = request == null ? null : request.getAttribute(ACTING_FOR, RequestAttributes.SCOPE_REQUEST);
290	        return steward instanceof String name ? " for=" + name : "";
291	    }
292	
293	    private void recordAfterCommit(String entry) {
294	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
295	            record(entry);
296	            return;
297	        }
298	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
299	            @Override
300	            public void afterCommit() {
301	                record(entry);
302	            }
303	        });
304	    }
305	
306	    /** A field naming a person: name=&lt;value&gt; or person=&lt;value&gt;, the value running to the next field. */
307	    private static final java.util.regex.Pattern PERSON_FIELD =
308	            java.util.regex.Pattern.compile(" (?:name|person)=(.*?)(?= [^ =]+=|$)");
309	
310	    /**
311	     * The sheet's lines exactly as the file holds them, newest first. With a name (not blank), only
312	     * the lines carrying name=&lt;it&gt; or person=&lt;it&gt;, compared as names are compared.
313	     */
314	    public List<String> linesOf(String sheetId, String name) {
315	        return name == null || name.isBlank() ? linesAbout(sheetId, null) : linesAbout(sheetId, Set.of(Person.keyOf(name)));
316	    }
317	
318	    /**
319	     * The sheet's lines exactly as the file holds them, newest first. With keys (not null), only the
320	     * lines carrying name=&lt;one&gt; or person=&lt;one&gt;, compared as names are compared.
321	     */
322	    public synchronized List<String> linesAbout(String sheetId, Set<String> keys) {
323	        List<String> lines;
324	        try {
325	            lines = Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
326	        } catch (IOException e) {
327	            throw new UncheckedIOException(e);
328	        }
329	        String sheetField = " sheet=" + sheetId + " ";
330	        List<String> shown = new ArrayList<>();
331	        for (String line : lines) {
332	            if (line.contains(sheetField) && (keys == null || isAbout(line, keys))) {
333	                shown.add(line);
334	            }
335	        }
336	        Collections.reverse(shown);
337	        return shown;
338	    }
339	
340	    /**
341	     * A claim's timeline: the sheet's lines exactly as the file holds them, newest first. With a number
342	     * (not null), the lines carrying number=&lt;it&gt;; without, the lines carrying no number that name
343	     * the person (compared as names are compared), the amount and the date together.
344	     */
345	    public List<String> linesOfClaim(String sheetId, String number, String person, String amount, String date) {
346	        if (number != null) {
347	            return linesAbout(sheetId, null).stream().filter((line) -> hasField(line, "number", number)).toList();
348	        }
349	        Set<String> keys = Set.of(Person.keyOf(person));
350	        return linesAbout(sheetId, keys).stream()
351	                .filter((line) -> !line.contains(" number=") && hasField(line, "amount", amount)
352	                        && hasField(line, "date", date))
353	                .toList();
354	    }
355	
356	    /** Whether the line carries the field with exactly the value, as a whole space-separated token. */
357	    private static boolean hasField(String line, String field, String value) {
358	        String token = " " + field + "=" + value;
359	        int at = line.indexOf(token);
360	        while (at >= 0) {
361	            int end = at + token.length();
362	            if (end == line.length() || line.charAt(end) == ' ') {
363	                return true;
364	            }
365	            at = line.indexOf(token, at + 1);
366	        }
367	        return false;
368	    }
369	
370	    private static boolean isAbout(String line, Set<String> keys) {
371	        Matcher field = PERSON_FIELD.matcher(line);
372	        while (field.find()) {
373	            if (keys.contains(Person.keyOf(field.group(1)))) {
374	                return true;
375	            }
376	        }
377	        return false;
378	    }
379	
380	    /**
381	     * The sheet's activity: for every user and every event in the sheet's lines, one line
382	     * &lt;user&gt; &lt;EVENT&gt; &lt;count&gt;, sorted by user then event.
383	     */
384	    public List<String> activityOf(String sheetId) {
385	        java.util.Map<String, java.util.Map<String, Integer>> counts = new java.util.TreeMap<>();
386	        for (String line : linesAbout(sheetId, null)) {
387	            int space = line.indexOf(' ');
388	            String event = space < 0 ? line : line.substring(0, space);
389	            String user = fieldValue(line, "by");
390	            if (event.isEmpty() || user == null) {
391	                continue;
392	            }
393	            counts.computeIfAbsent(user, (u) -> new java.util.TreeMap<>()).merge(event, 1, Integer::sum);
394	        }
395	        List<String> activity = new ArrayList<>();
396	        counts.forEach((user, events) -> events.forEach((event, count) -> activity.add(user + " " + event + " " + count)));
397	        return activity;
398	    }
399	
400	    /** The value of the line's first field, as the token after " field=", or null when it has none. */
401	    private static String fieldValue(String line, String field) {
402	        String token = " " + field + "=";
403	        int at = line.indexOf(token);
404	        if (at < 0) {
405	            return null;
406	        }
407	        int start = at + token.length();
408	        int end = line.indexOf(' ', start);
409	        return line.substring(start, end < 0 ? line.length() : end);
410	    }
411	
412	    /** Truncate the audit file. */
413	    public synchronized void clear() {
414	        try {
415	            Files.deleteIfExists(file);
416	        } catch (IOException e) {
417	            throw new UncheckedIOException(e);
418	        }
419	    }
420	}

