15	/**
16	 * The people of a sheet's whole tree (its root and all the root's descendants) whose name or an alias
17	 * contains a text, case ignored, each with their due-total as their own sheet shows it now.
18	 */
19	@Service
20	public class TreeSearch {
21	
22	    /** A person found: their sheet, name, grade in force on their sheet's today and due-total (null when n/a). */
23	    public record Found(String sheetId, String name, String grade, BigDecimal dueTotal) {
24	    }
25	
26	    private final SheetService sheets;
27	    private final PersonRepository people;
28	    private final Rollups rollups;
29	
30	    public TreeSearch(SheetService sheets, PersonRepository people, Rollups rollups) {
31	        this.sheets = sheets;
32	        this.people = people;
33	        this.rollups = rollups;
34	    }
35	
36	    /** The people found: this sheet's first in list order, then the other sheets' by sheet id. */
37	    @Transactional(readOnly = true)
38	    public List<Found> search(String sheetId, String text) {
39	        String key = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
40	        return walk(sheetId, person -> matches(person, key));
41	    }
42	
43	    /** All the people of the tree: this sheet's first in list order, then the other sheets' by sheet id. */
44	    @Transactional(readOnly = true)
45	    public List<Found> everyone(String sheetId) {
46	        return walk(sheetId, person -> true);
47	    }
48	
49	    private List<Found> walk(String sheetId, Predicate<Person> wanted) {
50	        List<String> others = new ArrayList<>(sheets.tree(sheetId));
51	        others.remove(sheetId);
52	        others.sort(null);
53	        List<String> order = new ArrayList<>();
54	        order.add(sheetId);
55	        order.addAll(others);
56	        List<Found> found = new ArrayList<>();
57	        for (String id : order) {
58	            Rollups.Rollup rollup = rollups.take(id);
59	            LocalDate today = sheets.today(id);
60	            for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
61	                if (wanted.test(person)) {
62	                    Rollups.Figures figures = rollup.people().get(person.getId());
63	                    found.add(new Found(id, person.getName(), person.gradeOn(today), figures == null ? null : figures.dueTotal()));
64	                }
65	            }
66	        }
67	        return found;
68	    }
69	
70	    private static boolean matches(Person person, String key) {
71	        if (person.getName().toLowerCase(Locale.ROOT).contains(key)) {
72	            return true;
73	        }
74	        return person.getAliases().stream().anyMatch(alias -> alias.toLowerCase(Locale.ROOT).contains(key));
75	    }
76	}
