336	   339	/**
337	   340	 * A person's timeline: one line per dated thing about them, in date order, and on one date their
338	   341	 * grade changes, then claims, then holds, then retirements, then unretirements (each kind by its line):
339	   342	 * "<date> grade <grade>", "<date> claim <amount> <status>", "<date> hold[ to <date>]", "<date> retired",
340	   343	 * "<date> unretired". The first grade, in force from the beginning of time, has no date and no line.
341	   344	 */
342	   345	export function timelineOf(person: PersonView, claims: TimelineClaim[]): string[] {
343	   346	  const entries: { date: string; kind: number; line: string }[] = [];
344	   347	  for (const g of person.grades) {
345	   348	    if (g.from !== null) entries.push({ date: g.from, kind: 0, line: `${g.from} grade ${g.grade}` });
346	   349	  }
347	   350	  for (const c of claims) entries.push({ date: c.date, kind: 1, line: `${c.date} claim ${c.amount} ${c.status}` });
348	   351	  for (const h of person.holds) {
349	   352	    entries.push({ date: h.from, kind: 2, line: `${h.from} hold${h.to ? ' to ' + h.to : ''}` });
350	   353	  }
351	   354	  const retired = [...(person.retirements ?? []).map((r) => r.from), ...(person.retiredFrom ? [person.retiredFrom] : [])];
352	   355	  for (const from of retired) entries.push({ date: from, kind: 3, line: `${from} retired` });
353	   356	  for (const r of person.retirements ?? []) entries.push({ date: r.to, kind: 4, line: `${r.to} unretired` });
354	   357	  return entries
355	   358	    .sort((a, b) => a.date.localeCompare(b.date) || a.kind - b.kind || (a.line < b.line ? -1 : a.line > b.line ? 1 : 0))
356	   359	    .map((e) => e.line);
357	   360	}
