20	import org.springframework.stereotype.Service;
21	
22	/**
23	 * The sheet's figures as the screen shows them: what each person has claimed, their due-total and
24	 * overdue-total, and the sheet's claimed-total, due-total and overdue-total. A change takes them
25	 * before it writes and has them audited after its own records, so every figure it moves is recorded.
26	 */
27	@Service
28	public class Rollups {
29	
30	    /** Shown in place of a due-total when the grade has no rate. */
31	    private static final String NO_RATE = "n/a";
32	
33	    /**
