122	    /**
123	     * A sheet's figures read from what is given, held in no store or not: the sheet (null when not found;
124	     * its today is the day they are read on), the basis their dues are read against, its people by id in
125	     * list order, its claims, and each person's cut total by id (none: no cut), which the cap covers too.
126	     */
127	    public Rollup take(Sheet sheet, Dues.Basis basis, Map<Long, Person> sheetPeople, Iterable<Claim> sheetClaims,
128	            Map<Long, BigDecimal> personCuts) {
129	        LocalDate today = sheet == null ? null : sheet.getToday();
130	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
131	        for (Claim claim : sheetClaims) {
132	            if (claim.getStatus().counts()) {
133	                byPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
134	            }
135	        }
136	        // The parts of shared claims their holders' due-totals count, by holder, from the claims that
137	        // count for their own person; each claim's figure as read here.
138	        // A holder whose grade has no rate has a part of 0.00, which gives them no figure.
139	        Map<Claim, BigDecimal> shared = new java.util.IdentityHashMap<>();
140	        Map<Long, BigDecimal> received = new LinkedHashMap<>();
141	        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
142	            Person person = entry.getValue();
143	            for (Claim claim : byPerson.getOrDefault(entry.getKey(), List.of())) {
144	                if (claim.getShares().isEmpty()
145	                        || !person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)) {
146	                    continue;
147	                }
148	                BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()), basis);
149	                if (figure == null) {
150	                    continue;
151	                }
152	                shared.put(claim, claim.sharedParts(share -> {
153	                    Person holder = sheetPeople.get(share.getPersonId());
154	                    BigDecimal part = dues.part(claim, share,
155	                            holder == null ? null : holder.gradeOn(claim.getDate()), figure, basis);
156	                    if (part != null) {
157	                        received.merge(share.getPersonId(), part, BigDecimal::add);
158	                    }
159	                    return part;
160	                }));
161	            }
162	        }
163	        Map<Long, Figures> figures = new LinkedHashMap<>();
164	        BigDecimal claimedTotal = zero();
165	        List<BigDecimal> dueFigures = new ArrayList<>();
166	        List<BigDecimal> overdueFigures = new ArrayList<>();
167	        int overdueCount = 0;
168	        for (Map.Entry<Long, Person> entry : sheetPeople.entrySet()) {
169	            Person person = entry.getValue();
170	            List<Claim> personClaims = byPerson.getOrDefault(entry.getKey(), List.of());
171	            BigDecimal claimed = zero();
172	            for (Claim claim : personClaims) {
173	                // What is claimed leaves out claims that correct another.
174	                if (person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today)
175	                        && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
176	                    claimed = claimed.add(claim.getAmount());
177	                }
178	            }
179	            List<Claim> counting = personClaims.stream()
180	                    .filter(claim -> person.countsLive(claim.getStatus(), claim.isStated(), claim.isDeferredOn(today), today))
181	                    .toList();
182	            BigDecimal due = zero();
183	            BigDecimal overdue = zero();
184	            BigDecimal settled = zero();
185	            BigDecimal settledShown = zero();
186	            BigDecimal openShown = zero();
187	            int personOverdue = 0;
188	            boolean figured = false;
189	            for (Claim claim : counting) {
190	                String grade = person.gradeOn(claim.getDate());
191	                boolean late = overdue(claim, sheet, grade);
192	                if (late) {
193	                    overdueCount++;
194	                    personOverdue++;
195	                }
196	                BigDecimal figure = dues.due(claim, grade, basis);
197	                if (figure != null) {
198	                    // A shared claim's own person counts its figure less its holders' parts.
199	                    due = due.add(shared.containsKey(claim) ? figure.subtract(shared.get(claim)) : figure);
200	                    figured = true;
201	                    if (late) {
202	                        overdue = overdue.add(figure);
203	                    }
204	                    if (claim.getStatus() == ClaimStatus.SETTLED) {
205	                        settledShown = settledShown.add(figure);
206	                    } else if (claim.getStatus().isOpen()) {
207	                        openShown = openShown.add(figure);
208	                    }
209	                    // The score's settled figures leave out claims that correct another.
210	                    if (claim.getStatus() == ClaimStatus.SETTLED
211	                            && (claim.getCorrects() == null || claim.getCorrects().isBlank())) {
212	                        settled = settled.add(figure);
213	                    }
214	                }
215	            }
216	            BigDecimal part = received.get(entry.getKey());
217	            if (part != null) {
218	                due = due.add(part);
219	                figured = true;
220	            }
221	            // As on the screen: n/a when the grade in force today has no rate, unless a claim has a
222	            // figure (a fixed one, or one at the grade in force on its own date).
223	            boolean rated = today != null && basis.rateInForce(person.gradeOn(today), today).isPresent();
224	            if (!rated && !figured) {
225	                due = null;
226	            }
227	            // A due-total is at most their cap (the one in force on their latest counting claim's date)
228	            // less their cut total, not below 0.00.
229	            if (sheet != null) {
230	                due = sheet.capped(due, personCuts.getOrDefault(entry.getKey(), zero()),
231	                        counting.stream().map(Claim::getDate).toList());
232	            }
233	            figures.put(entry.getKey(), new Figures(person.getName(), claimed, due, overdue, settled, personOverdue,
234	                    settledShown, openShown));
235	            claimedTotal = claimedTotal.add(claimed);
236	            if (due != null) {
237	                dueFigures.add(due);
238	            }
239	            overdueFigures.add(overdue);
240	        }
241	        return new Rollup(figures, claimedTotal, trimmed(dueFigures), trimmed(overdueFigures), overdueCount);
242	    }
