244	    /**
245	     * The sum of the people's figures, leaving out the single highest and the single lowest when there
246	     * are three or more.
247	     */
248	    static BigDecimal trimmed(List<BigDecimal> figures) {
249	        BigDecimal total = zero();
250	        for (BigDecimal figure : figures) {
251	            total = total.add(figure);
252	        }
253	        if (figures.size() >= 3) {
254	            BigDecimal highest = figures.stream().max(BigDecimal::compareTo).orElseThrow();
255	            BigDecimal lowest = figures.stream().min(BigDecimal::compareTo).orElseThrow();
256	            total = total.subtract(highest).subtract(lowest);
257	        }
258	        return total;
259	    }
