261	    /**
262	     * Record, once the change commits, one ROLLUP line per person whose figures moved since
263	     * {@code before} (a person new since then counts as moved), then a TOTALS line when any of the sheet's
264	     * totals moved, then one ALERT line per person, in list order, whose due-total went from at or below
265	     * the sheet's alert threshold (or none) to above it.
266	     */
267	    public void audit(String sheetId, String user, Rollup before) {
268	        Rollup after = take(sheetId);
269	        after.people().forEach((id, figures) -> {
270	            if (!figures.sameAs(before.people().get(id))) {
271	                audit.recordFiguresOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
272	                        + " claimed=" + figures.claimed().toPlainString() + " due-total=" + shown(figures.dueTotal())
273	                        + " overdue-total=" + figures.overdueTotal().toPlainString());
274	            }
275	        });
276	        if (!same(after.claimedTotal(), before.claimedTotal()) || !same(after.dueTotal(), before.dueTotal())
277	                || !same(after.overdueTotal(), before.overdueTotal())) {
278	            audit.recordFiguresOnCommit("TOTALS sheet=" + sheetId + " by=" + user
279	                    + " claimed-total=" + after.claimedTotal().toPlainString()
280	                    + " due-total=" + after.dueTotal().toPlainString()
281	                    + " overdue-total=" + after.overdueTotal().toPlainString());
282	        }
283	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
284	        if (threshold != null) {
285	            after.people().forEach((id, figures) -> {
286	                Figures was = before.people().get(id);
287	                if (above(figures.dueTotal(), threshold) && !(was != null && above(was.dueTotal(), threshold))) {
288	                    audit.recordFiguresOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
289	                            + " due-total=" + figures.dueTotal().toPlainString());
290	                }
291	            });
292	        }
293	    }
