300	    /**
301	     * Whether a claim is overdue: OPEN or PENDING with its due-by (plus its grade's grace, see
302	     * {@link Sheet#lateFrom}) before the sheet's today, and not deferred on it.
303	     */
304	    private static boolean overdue(Claim claim, Sheet sheet, String grade) {
305	        if (sheet == null) {
306	            return false;
307	        }
308	        LocalDate today = sheet.getToday();
309	        return claim.getStatus().isOpen() && sheet.lateFrom(claim.getDueBy(), grade, claim.getDate()).isBefore(today)
310	                && !claim.isDeferredOn(today);
311	    }
