119	   124	export function dueCents(amountCents: number, pct: string, times = 1, halfUp = false): number {
120	   125	  if (amountCents < 0) return -dueCents(-amountCents, pct, times, halfUp);
121	   126	  const [whole, frac = ''] = pct.split('.');
122	   127	  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
123	   128	  const exact = BigInt(amountCents) * basisPoints * BigInt(times);
124	   129	  const quotient = exact / 10000n;
