581	  constructor() {
582	    // A sheet load clears the timelines shown for the sheet before.
583	    effect(() => {
584	      this.session.sheet();
585	      this.session.loads();
586	      untracked(() => {
587	        this.timelineShows++;
588	        this.timelines.set({});
589	      });
590	    });
591	    // Put back the editor left open on this person's form (or, failing that, the one whose lock this
592	    // user holds) once their claims are shown.
593	    effect(() => {
594	      const claims = this.claims();
595	      if (this.restored || claims.length === 0) return;
596	      untracked(() => {
597	        this.restored = true;
598	        const me = this.session.user()?.trim();
599	        const id = this.editing() ?? claims.find((c) => c.status === 'DRAFT' && c.lockedBy === me)?.id ?? null;
600	        const claim = claims.find((c) => c.id === id && c.status === 'DRAFT');
601	        this.setEditing(claim?.id ?? null);
602	        if (claim) this.fill(claim);
603	      });
604	    });
605	    // An editor whose claim has left this person's DRAFT claims (reassigned, opened or gone) is closed:
606	    // the form goes back to adding a claim.
607	    effect(() => {
608	      const claims = this.claims();
609	      untracked(() => {
610	        const id = this.editing();
611	        if (this.restored && id !== null && !claims.some((c) => c.id === id && c.status === 'DRAFT')) this.reset();
612	      });
613	    });
