616	  /**
617	   * What is due on a claim: the due fixed when it was settled, or else the greater of the floor in
618	   * force on the claim's date and its figure — the rate figure its person's last statement bound it to,
619	   * or else its amount at the rate the person's grade has in force on the claim's date (n/a when it is
620	   * dated before every rate) — with its late charge (at the late percent in force on each 30-day
621	   * boundary) on top while it is overdue.
622	   */
623	  protected dueOf(claim: ClaimView): string {
624	    const late = { history: this.session.latePctHistory(), today: this.session.today() ?? '', grace: this.graceOf(claim) };
625	    const floor = cents(valueOn(this.session.floorHistory(), claim.date, '1.00'));
626	    const halfUp = roundsHalfUp(claim, this.claims(), this.session.policyDate(), late.today, this.session.roundingHistory());
627	    const figure = claimDueCents(claim, this.rates(), gradeOn(this.grades(), claim.date), floor, late, halfUp, this.inherited());
628	    return figure === null ? NO_RATE : money(figure);
629	  }
