40	/**
41	 * Whether a person's claim counts in the live totals, what they have claimed included: OPEN, PENDING and
42	 * SETTLED claims do, held or not, but not an OPEN or PENDING one once their retirement date is reached,
43	 * unless a statement has bound it, nor one deferred on the sheet's today.
44	 */
45	function countsLive(claim: ClaimView, person: PersonView, today: string): boolean {
46	  return counts(claim) && !deferred(claim, today) && !(isOpen(claim) && !claim.stated && leavesLive(person, today));
47	}
