49	/**
50	 * Whether a person's claim counts in a period's live figures: it counts by the status it had at the
51	 * end of the period's last day (see statusAt), one added after then not counting, and is left out,
52	 * as in the live totals, when deferred on today or when it is still OPEN or PENDING, unbound by a
53	 * statement and of a person whose retirement date is reached.
54	 */
55	function countsInPeriod(claim: ClaimView, person: PersonView, today: string, period: PeriodView): boolean {
56	  const then = statusAt(claim, period.to);
57	  if (then === null) return false;
58	  const countedThen = then === 'OPEN' || then === 'PENDING' || then === 'SETTLED';
59	  return countedThen && !deferred(claim, today) && !(isOpen(claim) && !claim.stated && leavesLive(person, today));
60	}
