62	/**
63	 * The sum of the people's figures in whole cents, leaving out the single highest and the single
64	 * lowest when there are three or more.
65	 */
66	function trimmedCents(figures: number[]): number {
67	  const total = figures.reduce((sum, f) => sum + f, 0);
68	  return figures.length >= 3 ? total - Math.max(...figures) - Math.min(...figures) : total;
69	}
