71	/** A whole number over a positive whole number, rounded half to even. */
72	function halfEven(numerator: number, denominator: number): number {
73	  const whole = Math.floor(numerator / denominator);
74	  const twice = (numerator - whole * denominator) * 2;
75	  return twice > denominator || (twice === denominator && whole % 2 !== 0) ? whole + 1 : whole;
76	}
77	
78	/** Cents times a share in hundredths of a percent, over 100: whole cents rounded half to even. */
79	function shareOf(cents: number, share: number): number {
80	  return halfEven(cents * share, 10000);
81	}
82	
83	/**
84	 * Cents times a share and a rate, each in hundredths of a percent, over 100 twice: whole cents rounded
85	 * half to even (or half up; a negative amount rounds as its opposite does). Worked in integers so it is exact.
86	 */
87	function partOf(amountCents: number, share: number, pct: number, halfUp: boolean): number {
88	  if (amountCents < 0) return -partOf(-amountCents, share, pct, halfUp);
89	  const exact = BigInt(amountCents) * BigInt(share) * BigInt(pct);
90	  const quotient = exact / 100_000_000n;
91	  const remainder = exact % 100_000_000n;
92	  const up = remainder > 50_000_000n || (remainder === 50_000_000n && (halfUp || quotient % 2n === 1n));
93	  return Number(up ? quotient + 1n : quotient);
94	}
