100	function activeOn(claims: ClaimView[], person: PersonView, today: string): boolean {
101	  if (today === '') return false;
102	  const since = new Date(Date.parse(today) - 29 * 86_400_000).toISOString().slice(0, 10);
103	  return claims.some((c) => isOpen(c) && countsLive(c, person, today) && since <= c.date && c.date <= today);
104	}
